/* MONTBLANC v5.0 — no personal records in source or GitHub Pages files.
   All real records live in a protected Supabase database with owner RLS.
   Unconfigured mode is an explicitly labelled, memory-only demo. */
const root = document.getElementById('app');
const cfg = window.LIFE_OS_CONFIG || {};
const configReady = Boolean(cfg.supabaseUrl && cfg.supabasePublishableKey && /^https:\/\//.test(cfg.supabaseUrl));
const LEGACY_TABLES = ['goals','tasks','daily_logs','ideas','idea_comments','journal_entries','finance_entries','weekly_reviews','skill_checks','ai_reports'];
const TABLES = [...LEGACY_TABLES,'experiments'];
let client=null, sessionUser=null, busy=false, toastTimer, localCryptoKey=null, lastInteraction=Date.now();
let state={page:'dashboard',profile:null,data:Object.fromEntries(TABLES.map(k=>[k,[]])),mode:'landing',demo:false,local:false,lowEnergy:false,modal:null,menu:false,filter:'all',errors:[],focusWindow:'month',taskScope:'today',reflectionMode:'quick',reflectionDate:null,analysisPeriod:'week',reflectionDraftTimer:null,reflectionDraftTouched:false};
const today=()=>localDate(new Date());
const VAULT_KEY='lifeos-v3-encrypted-vault'; // Preserve earlier local encrypted records on upgrade
const vaultStorage=(()=>{try{return window.localStorage}catch{return null}})();
function requireVaultStorage(){if(!vaultStorage)throw Error('Этот браузер запрещает локальное хранение. Используй обычную страницу HTTPS или облачный режим.');return vaultStorage}
const uid=()=>globalThis.crypto?.randomUUID?.()||`demo-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function plusDays(date,days){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+days);return localDate(d)}
function monthKey(d){return String(d||'').slice(0,7)}
function ruDate(str){if(!str)return '—';const d=new Date(`${String(str).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?String(str):new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric'}).format(d)}
function e(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function num(x){const n=Number(x);return Number.isFinite(n)?n:0}
function money(x){return '€'+num(x).toLocaleString('ru-RU',{maximumFractionDigits:2})}
function clamp(n,a=0,b=100){return Math.max(a,Math.min(b,n))}
function avg(xs){return xs.length?xs.reduce((a,b)=>a+num(b),0)/xs.length:0}
function deltaDays(from,to=today()){return Math.max(0,Math.floor((new Date(`${to}T12:00:00`)-new Date(`${from}T12:00:00`))/864e5))}
const ICONS={mountain:'<path d="M2 20l7.5-12 3.2 5 2.2-3.5L22 20H2Z"/><path d="M7 12l2.5 2 2.2-2"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0V3Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 13v5m-4 3h8m-6-3h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',layers:'<path d="m2 8 10-5 10 5-10 5L2 8Zm0 5 10 5 10-5M2 18l10 5 10-5"/>',compass:'<circle cx="12" cy="12" r="10"/><path d="m15 9-3 7-3-4 6-3Z"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',wallet:'<rect x="3" y="6" width="18" height="14" rx="2"/><path d="M3 9V5a2 2 0 0 1 2-2h13m3 9h-5a2 2 0 0 0 0 4h5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M4 2v20m0-20h16v20H6.5A2.5 2.5 0 0 1 4 19.5"/>',bulb:'<path d="M9 18h6m-5 4h4m-6-8a7 7 0 1 1 8 0l-1 3H9Z"/>',journal:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',chart:'<path d="M3 3v18h18M7 16l4-5 3 3 6-8"/>',settings:'<path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="m19.4 15 1-2-1-2-2-.5-.7-1.7.9-1.8-2-1.5-1.7 1-1.9-.5L10.5 4h-2l-.5 2-1.8.7-1.8-.9-1.5 2 1 1.7-.5 1.9L2 13l1 2 2 .5.7 1.7-.9 1.8 2 1.5 1.7-1 1.9.5 1.5 1.5h2l.5-2 1.8-.7 1.8.9 1.5-2-1-1.7Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m4 12 5 5L20 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',logout:'<path d="M10 17l5-5-5-5m5 5H3m10-8h5a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',spark:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8Z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m1-15a3 3 0 0 1 0 6m1 4a5 5 0 0 1 4 5"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.target}</svg>`}
function field(name,label,type='text',value='',extra=''){return `<div class="form-field"><label for="f_${e(name)}">${label}</label>${type==='textarea'?`<textarea class="control" name="${e(name)}" id="f_${e(name)}" ${extra}>${e(value)}</textarea>`:`<input class="control" id="f_${e(name)}" name="${e(name)}" type="${e(type)}" value="${e(value)}" ${extra}>`}</div>`}
function selectField(name,label,options,selected){return `<div class="form-field"><label for="f_${e(name)}">${label}</label><select class="control" id="f_${e(name)}" name="${e(name)}">${options.map(([v,l])=>`<option value="${e(v)}" ${String(v)===String(selected)?'selected':''}>${e(l)}</option>`).join('')}</select></div>`}
function formValues(form){return Object.fromEntries(new FormData(form).entries())}
function notify(msg,error=false){clearTimeout(toastTimer);document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast'+(error?' error':'');t.textContent=msg;document.body.appendChild(t);toastTimer=setTimeout(()=>t.remove(),4200)}
function shellTitle(){const map={tasks:'Планировщик',reflection:'Вечерний обзор',experiments:'Экспедиции и проверки',achievements:'Достижения',summit:'Моя вершина',sales:'Работа и продажи',dashboard:'Мой прогресс',today:'Сегодня',goals:'Карта целей',finance:'Финансы',habits:'Тело и энергия',learning:'1 час знаний',english:'Английский A1 → B1',ideas:'Банк идей',journal:'Личный дневник',review:'Недельный отчёт',monthly:'Итоги месяца',settings:'Настройки'};return map[state.page]||'MONTBLANC'}
const NAV=[['dashboard','Обзор','mountain'],['today','Мой день','sun'],['tasks','Задачи','check'],['reflection','Вечерний итог','journal'],['experiments','Эксперименты','compass'],['summit','Моя вершина','target'],['achievements','Награды','trophy'],['goals','Карта целей','target'],['finance','Финансы','wallet'],['sales','Работа и продажи','chart'],['learning','1 час знаний','book'],['english','Английский A1 → B1','book'],['habits','Тело и энергия','heart'],['ideas','Банк идей','bulb'],['journal','Дневник','journal'],['review','Итоги недели','chart'],['monthly','Итоги месяца + AI','spark'],['settings','Настройки','settings']];
function render(){captureDraftOnRender();if(state.mode==='landing')return renderLanding();if(state.mode==='local-auth')return renderLocalAuth();if(state.mode==='auth')return renderAuth();if(state.mode==='setup')return renderSetup();if(state.mode==='loading')return root.innerHTML='<div class="boot"><div class="boot-mark">L<span>●</span></div><p>Загружаем защищённые данные...</p></div>';renderShell()}
function renderLanding(){const existing=Boolean(vaultStorage?.getItem(VAULT_KEY));root.innerHTML=`<section class="auth-page"><div class="auth-panel local-entry"><div class="auth-brand"><span class="brand-icon brand-mountain">🏔</span> MONTBLANC <span class="pill">iPHONE · 6.0</span></div><div class="entry-mountain"><img src="./mountain-hero.webp" alt="Вершина Монблан на рассвете" /></div><h1>От базового лагеря<br><span class="accent">к своей вершине.</span></h1><p>Цели, заработок, английский, обучение, привычки и честная аналитика прогресса. Настоящий личный дневник — только после включения защищённого хранения.</p><div class="local-card"><b>🔒 Личный режим на этом устройстве</b><p class="small muted mt8">Данные сохраняются зашифрованными AES-GCM под твоим паролем. Без облачной синхронизации: на другом устройстве нужна резервная копия и восстановление.</p><button class="button mt14" data-action="local-open" ${vaultStorage?'':'disabled title="Хранилище недоступно"'}>${existing?'Открыть MONTBLANC':'Начать личную экспедицию'} ${icon('arrow')}</button></div><div class="notice mt20">Для реальных записей используйте устройство, которому доверяете, и надёжный пароль. Резервную копию нужно хранить отдельно. Шифрование не защищает от вредоносных расширений, взломанного устройства или подменённого кода сайта.</div><button class="button secondary mt14" data-action="demo">Смотреть демонстрацию (вымышленные данные)</button><div class="mt14"><label class="small muted" for="vault-restore-file">Восстановить зашифрованный архив</label><input id="vault-restore-file" type="file" accept=".json,application/json" class="control mt8"/></div><p class="small muted mt20">${configReady?'Также можно использовать облачный вход Supabase после настройки.':'Для синхронизации iPhone ↔ Mac потребуется защищённая облачная база или перенос резервной копии.'}</p></div></section>`}
function renderLocalAuth(){const existing=Boolean(vaultStorage?.getItem(VAULT_KEY));root.innerHTML=`<section class="auth-page"><div class="auth-panel local-entry"><div class="auth-brand"><span class="brand-icon brand-mountain">🏔</span> MONTBLANC <span class="pill">PRIVATE · LOCAL</span></div><h1>${existing?'Твоё пространство.':'Создай личное пространство.'}</h1><p>${existing?'Введи пароль, чтобы расшифровать записи на этом устройстве.':'Придумай уникальный пароль не короче 12 символов. Мы не сможем его восстановить.'}</p><form data-form="local-auth" class="stack"><div class="form-field"><label for="vault-pass">Пароль</label><input id="vault-pass" class="control" name="password" type="password" minlength="12" autocomplete="${existing?'current-password':'new-password'}" required/></div>${existing?'':`<div class="form-field"><label for="vault-confirm">Повтори пароль</label><input id="vault-confirm" class="control" name="confirm_password" type="password" minlength="12" autocomplete="new-password" required/></div>`}<button class="button" type="submit">${existing?'Разблокировать':'Начать личную экспедицию'} ${icon('arrow')}</button></form><button class="button ghost mt14" data-action="back-landing">← Назад</button><div class="safe mt20">${existing?'Если пароль потерян, данные без резервной копии и пароля восстановить нельзя.':'В этом режиме данные сохраняются в зашифрованном виде только в браузере. Нужна отдельная копия на случай очистки браузера.'}</div></div></section>`}
const utf8=(str)=>new TextEncoder().encode(str);
const b64=(a)=>{let binary="";for(let i=0;i<a.length;i+=32768)binary+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(binary)};
const fromB64=(s)=>Uint8Array.from(atob(s),x=>x.charCodeAt(0));
async function deriveVaultKey(password,salt){const material=await crypto.subtle.importKey('raw',utf8(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function sealVault(key,content,salt){const iv=crypto.getRandomValues(new Uint8Array(12));const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,utf8(JSON.stringify(content)));return {format:'life-os-v3-encrypted',version:3,iterations:310000,salt:b64(salt),iv:b64(iv),ciphertext:b64(new Uint8Array(ciphertext)),updated_at:new Date().toISOString()}}
let vaultWriteQueue=Promise.resolve();
async function persistLocal(){if(!state.local||!localCryptoKey)return;const old=JSON.parse(vaultStorage?.getItem(VAULT_KEY)||'null');if(!old)throw Error('Зашифрованное хранилище не найдено');const snapshot=JSON.stringify({profile:state.profile,data:state.data}),salt=fromB64(old.salt),key=localCryptoKey;vaultWriteQueue=vaultWriteQueue.catch(()=>{}).then(async()=>{const secured=await sealVault(key,JSON.parse(snapshot),salt);if(state.local&&localCryptoKey===key)requireVaultStorage().setItem(VAULT_KEY,JSON.stringify(secured))});return vaultWriteQueue} 
async function openLocal(password){requireVaultStorage();if(!globalThis.crypto?.subtle)throw Error('Шифрование доступно только в безопасном окружении HTTPS или localhost.');const saved=JSON.parse(vaultStorage?.getItem(VAULT_KEY)||'null');if(!saved){const salt=crypto.getRandomValues(new Uint8Array(16));localCryptoKey=await deriveVaultKey(password,salt);state.data=Object.fromEntries(TABLES.map(k=>[k,[]]));state.profile=null;state.local=true;state.demo=false;requireVaultStorage().setItem(VAULT_KEY,JSON.stringify(await sealVault(localCryptoKey,{profile:null,data:state.data},salt)));state.mode='setup';render();return}
 if(saved.format!=='life-os-v3-encrypted'||saved.version!==3)throw Error('Неизвестный формат шифрованного архива');const key=await deriveVaultKey(password,fromB64(saved.salt));const decrypted=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(saved.iv)},key,fromB64(saved.ciphertext));const obj=JSON.parse(new TextDecoder().decode(decrypted));if(!obj?.data||typeof obj.data!=='object')throw Error('Повреждённый архив');localCryptoKey=key;state.data=Object.fromEntries(TABLES.map(t=>[t,Array.isArray(obj.data[t])?obj.data[t]:[]]));state.profile=obj.profile||null;state.local=true;state.demo=false;state.mode=state.profile?'app':'setup';lastInteraction=Date.now();render()}
function lockLocal(){localCryptoKey=null;state.data=Object.fromEntries(TABLES.map(t=>[t,[]]));state.profile=null;state.local=false;state.mode='local-auth';state.modal=null;render()}
async function downloadEncrypted(){await vaultWriteQueue;const val=vaultStorage?.getItem(VAULT_KEY);if(!val)throw Error('Нет резервной копии');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([val],{type:'application/json'}));a.href=url;a.download=`life-os-encrypted-backup-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function renderAuth(){root.innerHTML=`<section class="auth-page"><div class="auth-panel"><div class="auth-brand"><span class="brand-icon brand-mountain">🏔</span> MONTBLANC <span class="pill">PRIVATE</span></div><h1>Твоё пространство.<br><span class="accent">Твои правила.</span></h1><p>Вход только для владельца. Данные защищены входом и индивидуальными правилами доступа к базе.</p><form class="auth-form" data-form="login">${field('email','Электронная почта','email','','autocomplete="email" required')}${field('password','Пароль','password','','autocomplete="current-password" required minlength="6"')}<button class="button" type="submit">Войти ${icon('arrow')}</button></form><div class="safe mt20">Нет регистрации для посторонних. Владелец создаётся в панели Supabase, а открытая регистрация отключается.</div></div></section>`}
function renderSetup(){root.innerHTML=`<section class="auth-page"><div class="setup-hero"><div class="card"><div class="eyebrow">Первый запуск · Приватная настройка</div><h1 class="setup-heading" style="margin-top:13px">Давай зафиксируем<br><span class="accent">твою точку А.</span></h1><p class="muted mb14" style="line-height:1.6">Введённые цифры сохранятся в зашифрованном хранилище этого устройства или в защищённой базе при облачном входе. Ничего личного не записывается в исходный код сайта.</p><form data-form="setup" class="stack"><div class="form-grid">${field('income_baseline','Стабильный доход сейчас, €/мес','number','0','min="0" step="0.01" required')}${field('debt_baseline','Текущий долг, €','number','0','min="0" step="0.01" required')}${field('goal_90','Цель дохода на 90 дней, €','number','1500','min="0" step="1" required')}${field('goal_year','Цель на 12 месяцев, €','number','2500','min="0" step="1" required')}${field('social_baseline','Соцсети в среднем, мин/день','number','120','min="0" step="1" required')}${field('sport_baseline','Тренировок в неделю','number','1','min="0" max="14" step="1" required')}${field('focus_title','Мой фокус на ближайшие 14 дней','text','Проверить спрос и получить первого клиента','required')}</div>${field('why_text','Ради чего я начинаю?','textarea','','placeholder="Пиши своими словами, не нужно идеальных формулировок"')}${field('vision_text','Как я хочу жить через год?','textarea','','placeholder="Три конкретные перемены"')}<div class="safe">Это не экзамен. Данные можно изменить в разделе «Настройки».</div><div class="form-actions"><button type="submit" class="button">Начать восхождение ${icon('arrow')}</button></div></form></div></div></section>`}
function renderShell(){const p=state.profile||{};const overall=overallProgress();root.innerHTML=`<div class="shell ${state.menu?'menuopen':''}"><div class="nav-shade" data-action="menu"></div><aside class="sidebar"><div class="brand"><div class="brand-icon brand-mountain">🏔</div><div><div class="brand-name">MONTBLANC</div><div class="brand-caption">FROM ZERO TO SUMMIT</div></div></div><nav class="nav"><div class="navlabel">Система</div>${NAV.slice(0,7).map(([id,label,ico])=>`<button class="navbtn ${state.page===id?'active':''}" data-page="${id}">${icon(ico)} ${label}</button>`).join('')}<div class="navlabel">Развитие</div>${NAV.slice(7,17).map(([id,label,ico])=>`<button class="navbtn ${state.page===id?'active':''}" data-page="${id}">${icon(ico)} ${label}</button>`).join('')}<div class="navlabel">Профиль</div><button class="navbtn ${state.page==='settings'?'active':''}" data-page="settings">${icon('settings')} Настройки</button></nav><div class="sidebar-foot"><div class="spread"><span class="micro muted">Выполнение ориентиров</span><span class="micro accent">${overall}%</span></div><div class="side-progress"><span style="width:${overall}%"></span></div><p class="micro muted mt14">Ежедневные шаги создают реальные изменения.</p></div></aside><main class="main"><header class="topbar"><div class="top-left"><button class="iconbtn menu-toggle" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><span class="small muted">ЛИЧНОЕ ПРОСТРАНСТВО <span class="accent">/</span> ${e(shellTitle())}</span></div><div class="topbar-right"><div class="date-chip">${icon('calendar')} ${ruDate(today())}</div><span class="pill ${state.demo?'gold':''}">${state.demo?'ДЕМО · без сохранения':state.local?'🔒 Локально':'● Облачный доступ'}</span></div></header>${state.demo?'<div class="notice" style="margin:17px auto 0;max-width:1280px">Демонстрация: все цифры вымышлены, данные не сохраняются после обновления. Не вводи здесь личную или медицинскую информацию.</div>':''}<div class="content">${renderPage()}</div></main></div><nav class="mobile-dock" aria-label="Основные разделы">${[['dashboard','Вершина','mountain'],['tasks','Задачи','check'],['reflection','Вечер','journal'],['experiments','Поиск','compass'],['achievements','Награды','trophy']].map(([id,l,ic])=>`<button data-page="${id}" class="${state.page===id?'active':''}" aria-label="${l}">${icon(ic)}<span>${l}</span></button>`).join('')}</nav>${state.modal?renderModal(state.modal):''}`}
function pageHead(kicker,title,sub,button=''){return `<div class="pagehead"><div><div class="eyebrow">${e(kicker)}</div><h1 style="margin-top:10px">${e(title)}</h1><p>${e(sub)}</p></div>${button}</div>`}
function kpi(label,value,meta,ic='target',cls=''){return `<div class="card"><div class="spread"><div class="kpi-label">${e(label)}</div><div class="kpi-icon">${icon(ic)}</div></div><div class="kpi-value ${cls}">${value}</div><div class="kpi-meta">${e(meta)}</div></div>`}
function progress(goal){const a=num(goal.start_value),c=num(goal.current_value),t=num(goal.target_value);if(goal.direction==='down'){if(a<=t)return c<=t?100:0;return clamp(100*(a-c)/(a-t))}if(t<=a)return c>=t?100:0;return clamp(100*(c-a)/(t-a))}
function measuredGoal(g){const st=weekStats();switch(g.metric_key){case 'monthly_income':return {...g,current_value:monthIncome()};case 'weekly_sport':return {...g,current_value:st.sport};case 'daily_english':return {...g,current_value:st.logs?Math.round(st.english/st.logs):0};case 'weekly_english':return {...g,current_value:st.english};case 'daily_learning':return {...g,current_value:st.logs?Math.round(st.learning/st.logs):0};case 'reserve_rate':return {...g,current_value:monthIncome()>0?Math.round(100*monthReserve()/monthIncome()):0};case 'english_skill':{const skills=['speaking','listening','reading','writing'],level={A1:1,A2:2,B1:3},checks=state.data.skill_checks||[];const grades=skills.map(k=>{const last=checks.filter(x=>x.skill===k).sort((a,b)=>String(b.assessed_on).localeCompare(String(a.assessed_on)))[0];return level[last?.level]||1});return {...g,current_value:Math.round(avg(grades)*100)/100}}case 'weekly_family':return {...g,current_value:st.family};case 'daily_social':return {...g,current_value:st.socialAverage===null?num(g.start_value):st.socialAverage};default:return g}}
function overallProgress(){const gs=state.data.goals.filter(x=>x.horizon==='90'&&x.status!=='paused');return gs.length?Math.round(avg(gs.map(g=>progress(measuredGoal(g))))):0}
function currentDebt(){const snapshots=state.data.finance_entries.filter(x=>x.kind==='debt_balance').sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date))||String(b.created_at||'').localeCompare(String(a.created_at||'')));return snapshots.length?num(snapshots[0].amount_eur):num(state.profile?.debt_baseline)}
function monthIncome(month=monthKey(today())){return state.data.finance_entries.filter(x=>x.kind==='income'&&monthKey(x.entry_date)===month).reduce((sum,x)=>sum+num(x.amount_eur),0)}
function monthReserve(month=monthKey(today())){return state.data.finance_entries.filter(x=>monthKey(x.entry_date)===month&&(x.kind==='reserve'||x.kind==='reserve_withdrawal')).reduce((s,x)=>s+(x.kind==='reserve'?num(x.amount_eur):-num(x.amount_eur)),0)}
function reserveBalance(){return state.data.finance_entries.reduce((s,x)=>s+(x.kind==='reserve'?num(x.amount_eur):x.kind==='reserve_withdrawal'?-num(x.amount_eur):0),0)}
function addMonths(date,count){const d=new Date(`${date}T12:00:00`);const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+count);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return localDate(d)}
function logBetween(from,to){return state.data.daily_logs.filter(x=>x.log_date>=from&&x.log_date<=to)}
function sumOf(rows,key){return rows.reduce((s,x)=>s+num(x[key]),0)}
function changeHint(current,previous,unit=''){if(previous===null)return 'Нет данных для сравнения';const diff=Math.round(current-previous);return `${diff>0?'+':''}${diff} ${unit} к предыдущему периоду`}
function lastDays(n=7){return Array.from({length:n},(_,i)=>plusDays(today(),i-(n-1)))}
function weekLogs(){const start=plusDays(today(),-6);return state.data.daily_logs.filter(x=>x.log_date>=start&&x.log_date<=today())}
function weekStats(){const logs=weekLogs(),sum=k=>logs.reduce((a,x)=>a+num(x[k]),0);return {logs:logs.length,focus:sum('focus_min'),english:sum('english_min'),learning:sum('learning_min'),learningDays:logs.filter(x=>num(x.learning_min)>=60).length,englishDays:logs.filter(x=>num(x.english_min)>=60).length,sport:logs.filter(x=>num(x.exercise_min)>=20).length,family:sum('family_min'),socialAverage:logs.length?Math.round(avg(logs.map(x=>x.social_min))):null,sleepAverage:logs.filter(x=>x.sleep_hours!==null&&x.sleep_hours!==undefined).length?avg(logs.filter(x=>x.sleep_hours!==null&&x.sleep_hours!==undefined).map(x=>x.sleep_hours)):null,energyAverage:logs.some(x=>x.energy!=null)?avg(logs.filter(x=>x.energy!=null).map(normalizedEnergy)):null,completed:state.data.tasks.filter(t=>t.completed&&t.task_date>=plusDays(today(),-6)&&t.task_date<=today()).length}}
function goalCards(list){if(!list.length)return '<div class="empty">Пока нет целей. Начни с одной измеримой.</div>';return list.map(original=>{const g=measuredGoal(original),percent=Math.round(progress(g)),start=state.profile?.started_at||today(),total=g.deadline?Math.max(1,deltaDays(start,g.deadline)):0,passed=g.deadline?clamp(deltaDays(start,today())/total*100):0,habit=['weekly_sport','weekly_english','daily_learning','weekly_family','daily_social','reserve_rate'].includes(g.metric_key),noData=(g.metric_key==='reserve_rate'&&monthIncome()<=0)||(['weekly_sport','weekly_english','daily_learning','weekly_family','daily_social'].includes(g.metric_key)&&weekStats().logs===0)||(g.metric_key==='monthly_income'&&!state.data.finance_entries.some(x=>x.kind==='income'&&monthKey(x.entry_date)===monthKey(today()))),status=noData?'Недостаточно данных':percent>=100?'Цель достигнута':habit?'Текущий ритм':passed>65&&percent<25?'Нужно скорректировать план':'В работе';return `<div class="goal"><div class="goal-main"><div><span class="pill gray">${e(catLabel(g.category))}</span><h3 class="mt8">${e(g.title)}</h3><p class="small muted mt8">${e(g.description||'')}${g.deadline?' · срок: '+ruDate(g.deadline):''}</p></div><div class="goal-list-actions"><button class="button small secondary" data-action="edit-goal" data-id="${e(g.id)}">Изменить</button></div></div><div class="spread small"><span>Сейчас: <b>${e(g.current_value)} ${e(g.unit)}</b> · цель: <b>${e(g.target_value)} ${e(g.unit)}</b></span><span class="accent">${noData?'—':percent+'%'}</span></div><div class="progress-track"><div class="progress-fill" style="width:${noData?0:percent}%"></div></div>${g.deadline?`<div class="spread micro muted"><span>${e(status)}</span><span>До ${ruDate(g.deadline)}</span></div>`:`<div class="micro muted">${e(status)}</div>`}${g.next_action?`<p class="small muted mt14">Следующий шаг: ${e(g.next_action)}</p>`:''}</div>`}).join('')}
function catLabel(s){return ({finance:'Доход',health:'Тело',growth:'Развитие',family:'Семья',focus:'Концентрация',travel:'Путешествия',capital:'Капитал',other:'Другое'})[s]||'Другое'}
function svgChart(values,labels,{target=null,min=0,max=null,format='number'}={}){const W=680,H=240,L=51,R=17,T=19,B=41;const actual=values.map(v=>v===null||v===undefined?null:num(v));const seen=actual.filter(v=>v!==null);const hi=Math.max(max??0,target??0,...seen,1),lo=Math.min(min,0);const span=Math.max(1,hi-lo);const x=i=>L+(W-L-R)*(i/Math.max(1,values.length-1)),y=v=>T+(H-T-B)*(1-(v-lo)/span);const pts=actual.map((v,i)=>v===null?null:[x(i),y(v)]);const groups=[];let g=[];for(const p of pts){if(p)g.push(p);else if(g.length){groups.push(g);g=[]}}if(g.length)groups.push(g);const paths=groups.map(s=>{const d=s.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');const area=d+` L${s.at(-1)[0].toFixed(1)},${y(lo)} L${s[0][0].toFixed(1)},${y(lo)} Z`;return `<path d="${area}" fill="url(#area-life)"/><path class="chart-line" d="${d}"/>`}).join('');const fmt=v=>format==='money'?money(v):Math.round(v).toLocaleString('ru-RU');const tickIndices=new Set([0,Math.round((values.length-1)/4),Math.round((values.length-1)/2),Math.round(3*(values.length-1)/4),values.length-1]);return `<svg class="chart" role="img" aria-label="График изменений, пустые значения означают отсутствие записи" viewBox="0 0 ${W} ${H}"><defs><linearGradient id="area-life" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#4b89ff" stop-opacity=".26"/><stop offset="100%" stop-color="#4b89ff" stop-opacity=".015"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const yy=T+(H-T-B)*i/4;return `<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="chart-label" x="${L-9}" y="${yy+4}" text-anchor="end">${e(fmt(hi-(hi-lo)*i/4))}</text>`}).join('')}${target!==null?`<line x1="${L}" x2="${W-R}" y1="${y(target)}" y2="${y(target)}" stroke="#cf9e51" stroke-width="1.5" stroke-dasharray="6 6"/>`:''}${paths}${pts.map((p,i)=>p?`<circle class="chart-dot" cx="${p[0]}" cy="${p[1]}" r="3.2"><title>${e(labels[i])}: ${e(fmt(actual[i]))}</title></circle>`:'').join('')}${labels.map((l,i)=>tickIndices.has(i)?`<text class="chart-label" x="${x(i)}" y="${H-12}" text-anchor="middle">${e(l)}</text>`:'').join('')}</svg>${!seen.length?'<p class="small muted">Пока нет записей. Отсутствие данных не считается нулевым результатом.</p>':''}`}
function ring(pct,title,center,{size=126,color='#366ce5',dark=false}={}){const radius=42,circ=2*Math.PI*radius,dash=circ*clamp(pct)/100;return `<div class="ring-wrap" style="width:${size}px;height:${size}px"><svg viewBox="0 0 110 110" width="${size}" height="${size}" aria-label="${e(title||'Прогресс')}: ${Math.round(pct)}%"><circle cx="55" cy="55" r="42" stroke="${dark?'#ffffff30':'#e8edf4'}" stroke-width="10" fill="none"/><circle cx="55" cy="55" r="42" stroke="${color}" stroke-width="10" stroke-linecap="round" fill="none" stroke-dasharray="${dash} ${circ}" transform="rotate(-90 55 55)"/><text x="55" y="56" dominant-baseline="middle" text-anchor="middle" fill="${dark?'#fff':'#192a42'}" font-size="${String(center).length>9?13:16}" font-weight="770">${e(center)}</text></svg>${title?`<span class="ring-label">${e(title)}</span>`:''}</div>`}
function incomeChart(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-i));return localDate(d).slice(0,7)});const values=months.map(m=>state.data.finance_entries.some(x=>x.kind==='income'&&monthKey(x.entry_date)===m)?monthIncome(m):null);return svgChart(values,months.map(m=>{const dt=new Date(`${m}-01T12:00:00`);return new Intl.DateTimeFormat('ru-RU',{month:'short'}).format(dt)}),{target:num(state.profile?.goal_90)||1500,format:'money'})}
function heatmap(){return `<div class="calendar-heat">${lastDays(28).map(date=>{const d=state.data.daily_logs.find(x=>x.log_date===date);const tasks=state.data.tasks.filter(x=>x.task_date===date);const score=d?(num(d.focus_min)>=30?2:1)+(num(d.english_min)>=10?1:0)+(tasks.some(x=>x.completed)?1:0):0;return `<div class="heatcell ${score===0?'':score===1?'low':score===2?'medium':'high'}" title="${e(date)} · ${d?'есть запись':'без записи'}"></div>`}).join('')}</div><p class="footnote mt8">28 дней · более яркий цвет означает больше выполненных небольших действий. Пустые дни не обнуляют прогресс.</p>`}
function todayTasks(){const items=state.data.tasks.filter(t=>t.task_date&&t.task_date<=today()&&t.status!=='cancelled'&&t.status!=='skipped').sort((a,b)=>(Number(a.completed)-Number(b.completed))||String(a.task_date).localeCompare(String(b.task_date)));return items.length?items.slice(0,8).map(t=>`<div class="task ${t.completed?'done':''}"><button class="check ${t.completed?'checked':''}" aria-label="${t.completed?'Отменить отметку':'Выполнить задачу'}" data-action="toggle-task" data-id="${e(t.id)}">${t.completed?'✓':''}</button><div style="flex:1"><div class="task-title">${e(t.title)}</div><div class="task-meta">${e(catLabel(t.category))} · ${e(t.task_date===today()?'Сегодня':ruDate(t.task_date))} ${t.is_main?'· Главный шаг':''}</div></div><button class="iconbtn" data-action="edit-task" data-id="${e(t.id)}" aria-label="Изменить задачу">···</button></div>`).join(''):'<div class="empty">Сегодня пока нет задач. Выбери одно реальное действие.</div>'}
function salesSummary(days=30){const logs=logBetween(plusDays(today(),1-days),today());return {days:logs.length,contacts:sumOf(logs,'sales_contacts'),replies:sumOf(logs,'sales_replies'),calls:sumOf(logs,'sales_calls'),offers:sumOf(logs,'sales_offers'),paid:sumOf(logs,'sales_paid')}}
function growthSignals(){const logs=weekLogs(),n=logs.length,s=salesSummary(7);if(n<4)return {score:null,coverage:n,signals:[],reason:'Для честного Growth Score нужны хотя бы 4 записи за 7 дней.'};const vals=[{name:'Реальные контакты',value:clamp(s.contacts/Math.max(1,n*8)*100),weight:.30,detail:`${s.contacts} контактов · цель ≈${n*8}`},{name:'Английский',value:clamp(sumOf(logs,'english_min')/(60*n)*100),weight:.22,detail:`${sumOf(logs,'english_min')} минут`},{name:'Учёба',value:clamp(sumOf(logs,'learning_min')/(60*n)*100),weight:.18,detail:`${sumOf(logs,'learning_min')} минут`},{name:'Спорт',value:clamp(logs.filter(x=>num(x.exercise_min)>=20).length/3*100),weight:.15,detail:'3 тренировки за неделю'},{name:'Концентрация',value:clamp(sumOf(logs,'focus_min')/(90*n)*100),weight:.15,detail:'90 минут за день с записью'}];return {score:Math.round(vals.reduce((sum,v)=>sum+v.value*v.weight,0)),coverage:n,signals:vals,reason:'Индекс отражает регулярность действий, НЕ рост дохода, владение английским или ценность человека.'}}
function growthAdvice(){const s=salesSummary(7),g=growthSignals();if(g.coverage<4)return 'Сначала записывай действия хотя бы четыре дня. Без данных приложение не будет угадывать причину отставания.';if(s.contacts<10)return 'Главное узкое место — мало контактов с клиентами. Выбери одну услугу и отправь пять адресных предложений сегодня.';if(s.contacts>=20&&s.replies===0)return 'Контакты есть, но ответов нет. Пересмотри сегмент, текст сообщения и конкретную пользу для покупателя.';if(s.replies>=5&&s.offers===0)return 'Есть интерес, но нет офферов. Сформулируй цену и предложи клиенту следующий шаг.';if(s.offers>=5&&s.paid===0)return 'Есть предложения, но нет оплат. Разбери пять возражений, проверь ценность и качество оффера.';return 'Продолжай одну выбранную гипотезу. Сопоставляй реальные оплаченные заказы с действиями, а не только с часами работы.'}
function renderSales(){const t=state.data.daily_logs.find(x=>x.log_date===today())||{},s=salesSummary(30),n=salesSummary(7),logs=lastDays(30),recorded=logBetween(plusDays(today(),-29),today()).length;const cells=[['Контакты',s.contacts,'Охват потенциальных клиентов'],['Ответы',s.replies,'Значимый ответ'],['Разговоры',s.calls,'Созвоны и переговоры'],['Предложения',s.offers,'Отправленные офферы'],['Оплаты',s.paid,'Подтверждённые новые заказы']];return `${pageHead('ВЫХОД ИЗ ЗАСТОЯ','Работа и продажи','Здесь важны не дизайны, исследования и идеи, а настоящие контакты, диалоги и оплаты.',`<button class="button" data-page="ideas">Банк идей ${icon('arrow')}</button>`)}<section class="card focus-feature"><div class="eyebrow">ОДНА АКТИВНАЯ ГИПОТЕЗА</div><h2 class="mt8">${e(state.profile?.focus_title||'Проверить спрос на одну услугу')}</h2><p class="small muted mt8">Не меняй направление из-за скуки на третий день. Проверь его реальными разговорами и платежами.</p></section><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Сегодняшняя воронка</h2><span class="pill gray">${ruDate(today())}</span></div><form class="stack" data-form="sales"><div class="form-grid">${field('sales_contacts','Кому написал','number',t.sales_contacts??0,'required min="0" max="10000" step="1"')}${field('sales_replies','Ответили','number',t.sales_replies??0,'required min="0" max="10000" step="1"')}${field('sales_calls','Разговоры','number',t.sales_calls??0,'required min="0" max="10000" step="1"')}${field('sales_offers','Отправил предложения','number',t.sales_offers??0,'required min="0" max="10000" step="1"')}${field('sales_paid','Новых оплаченных заказов','number',t.sales_paid??0,'required min="0" max="10000" step="1"')}</div><button type="submit" class="button">Сохранить результаты</button></form><p class="footnote mt14">Это действия и количество заказов. Суммы фактически полученных денег записывай в разделе «Финансы».</p></section><section class="card"><div class="card-header"><h2>Воронка · 30 дней</h2><span class="pill gray">${recorded}/30 дней с данными</span></div>${cells.map((x,i)=>`<div class="funnel-row"><div class="spread"><span class="small muted">${e(x[0])}</span><b>${x[1]}</b></div><div class="progress-track"><div class="progress-fill" style="width:${s.contacts?clamp(x[1]/s.contacts*100):0}%"></div></div></div>`).join('')}<div class="insight-strip mt20">${e(growthAdvice())}</div><p class="footnote mt14">Показатели этапов могут относиться к разным клиентам и дням, поэтому их нельзя считать точной конверсией одного потока.</p></section></div><section class="card mt20"><div class="card-header"><h2>Контакты с клиентами · 30 дней</h2><span class="pill gray">Цель: 8 контактов в рабочий день</span></div>${svgChart(logs.map(d=>state.data.daily_logs.find(x=>x.log_date===d)?.sales_contacts??null),logs.map(d=>d.slice(8)),{target:8})}<p class="small muted mt14">За последние 7 дней: ${n.contacts} контактов, ${n.replies} ответов и ${n.paid} оплат. Проверяй закономерности, не делай выводов по двум сообщениям.</p></section>`}
function renderGrowthPanel(){const g=growthSignals();return `<div class="grid cols2 mt20"><section class="card growth-card"><div class="spread"><div><div class="eyebrow">GROWTH INDEX · 7 ДНЕЙ</div><h2 class="mt8">Ритм реальных действий</h2></div><span class="pill gray">${g.coverage}/7 записей</span></div><div class="growth-hero"><strong>${g.score===null?'—':g.score+' / 100'}</strong><span>${g.score===null?'Недостаточно данных':'Процессы, не результаты'}</span></div>${g.signals.map(x=>`<div class="growth-row"><div class="spread"><span>${e(x.name)}</span><b>${Math.round(x.value)}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${x.value}%"></div></div><div class="footnote">${e(x.detail)}</div></div>`).join('')}<p class="footnote mt14">${e(g.reason)}</p></section><section class="card growth-card"><div class="eyebrow">ДИАГНОСТИКА БЕЗ САМООБМАНА</div><h2 class="mt8">Что тормозит результат?</h2><div class="growth-advice mt20">${icon('spark')} <div>${e(growthAdvice())}</div></div><div class="insight-strip mt20">Большой доход — результат, а не галочка. Сначала создавай воспроизводимый процесс продаж.</div><button class="button secondary mt20" data-page="sales">Посмотреть воронку продаж ${icon('arrow')}</button><div class="gentle-note mt14">На тяжёлый день: один адресный контакт, 10 минут английского и короткая прогулка — тоже возвращение к маршруту.</div></section></div>`}
function renderDashboard(){const st=weekStats(),logs=logBetween(plusDays(today(),-29),today()),focus=state.profile?.focus_title||'Проверить спрос на одну услугу',income=monthIncome(),goal=num(state.profile?.goal_90)||1500,debt=currentDebt(),reserve=monthReserve(),need=income*.2,days=lastDays(30),start=state.profile?.started_at||today(),completed=state.data.tasks.filter(t=>t.completed&&t.task_date>=plusDays(today(),-29)).length;const study=sumOf(logs,'learning_min'),eng=sumOf(logs,'english_min');const coverage=logs.length;const indicators=[{title:'Доход',value:money(income),note:`Из ${money(goal)} на 90 дней`,pct:clamp(income/Math.max(goal,1)*100),color:'blue'},{title:'Учёба · 30 дней',value:`${Math.round(study/60*10)/10} ч`,note:`${logs.filter(l=>num(l.learning_min)>=60).length} дней с 60+ минутами`,pct:clamp(study/(30*60)*100),color:'purple'},{title:'Английский · 30 дней',value:`${Math.round(eng/60*10)/10} ч`,note:'Цель: 60 минут ежедневно',pct:clamp(eng/(30*60)*100),color:'cyan'},{title:'Тело и спорт',value:`${st.sport} / 3`,note:'Тренировок за 7 дней',pct:clamp(st.sport/3*100),color:'green'}];return `${renderMountainWelcome()}${pageHead('ТВОЙ ЛИЧНЫЙ КОКПИТ','Каждый день — сильнее.','Не нужно ждать мотивации. Смотри на данные, делай следующий шаг, отмечай результат.',`<button class="button" data-page="today">Открыть мой день ${icon('arrow')}</button>`)}<section class="hero-panel"><div class="hero-copy"><div class="hero-overline"><span class="live-dot"></span> ТВОЙ МАРШРУТ · 90 ДНЕЙ</div><h2>От намерений<br>к реальным результатам.</h2><p>${e(focus)}</p><div class="hero-actions"><button class="button white" data-page="today">Начать сегодня ${icon('arrow')}</button><button class="button glass" data-page="goals">Посмотреть цели</button></div></div><div class="hero-ring">${ring(Math.round(clamp(income/Math.max(goal,1)*100)),'Доход к цели',money(income),{size:168,color:'#bad9ff',dark:true})}<span class="hero-ring-caption">Цель ${money(goal)} / мес</span></div></section><div class="grid cols4 mt20">${indicators.map(i=>`<div class="card signal-card"><div class="kpi-label">${e(i.title)}</div><div class="kpi-value">${i.value}</div><div class="kpi-meta">${e(i.note)}</div><div class="microbar"><span class="${i.color}" style="width:${i.pct}%"></span></div></div>`).join('')}</div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><div><div class="eyebrow">ПАНЕЛЬ РОСТА</div><h2 class="mt8">Фокус · 30 дней</h2></div><span class="pill gray">${coverage}/30 дней с данными</span></div>${svgChart(days.map(d=>logs.find(x=>x.log_date===d)?.focus_min??null),days.map(d=>d.slice(5)),{target:90})}<div class="insight-strip">${icon('spark')} ${coverage<7?'Первые 7 записей дадут начальную картину концентрации.':`Записано ${Math.round(sumOf(logs,'focus_min')/60)} ч работы с фокусом. Смотри, сопровождается ли это реальными продажами.`}</div></section><section class="card"><div class="card-header"><div><div class="eyebrow">ЕЖЕДНЕВНЫЙ ПЛАН</div><h2 class="mt8">Что сделать сегодня</h2></div><button class="button small secondary" data-action="new-task">${icon('plus')} Добавить</button></div>${todayTasks()}<div class="gentle-note mt14">В тяжёлый день — один шаг на 10 минут. Нет необходимости компенсировать пропуски.</div></section></div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Четыре направления роста</h2><span class="pill gray">По фактам, не по ощущениям</span></div><div class="four-rings">${indicators.map(i=>`<div class="ring-metric">${ring(Math.round(i.pct),'',i.value,{size:114,color:i.color==='purple'?'#8767e7':i.color==='cyan'?'#19a3d1':i.color==='green'?'#2fb58d':'#366ce5'})}<div class="micro muted">${e(i.title)}</div></div>`).join('')}</div><div class="footnote mt14">Кольца показывают выполнение конкретного числового ориентира, а не «качество личности».</div></section><section class="card"><div class="card-header"><h2>Деньги и защита семьи</h2><button class="button small ghost" data-page="finance">Финансы ${icon('arrow')}</button></div><div class="finance-mini"><div><span>Доход за месяц</span><strong>${money(income)}</strong></div><div><span>20% в резерв · план</span><strong>${money(need)}</strong></div><div><span>Переведено в резерв</span><strong>${money(reserve)}</strong></div><div><span>Остаток долга (по записи)</span><strong>${money(debt)}</strong></div></div><div class="insight-strip">${income>0?`До цели по резерву за месяц не хватает ${money(Math.max(0,need-reserve))}. Перевод нужно делать отдельно через банк.`:'Когда появится поступление, MONTBLANC посчитает 20% для отдельного счёта.'}</div></section></div><div class="card mt20"><div class="card-header"><h2>Твоя последовательность за 28 дней</h2><button class="button small ghost" data-page="monthly">Понять отставания ${icon('arrow')}</button></div>${heatmap()}<div class="footnote mt14">${completed} выполненных задач за 30 дней · ${coverage} дневных записей. Если в календаре пробел — это отсутствие данных, а не провал.</div></div>${renderGrowthPanel()}`}
function renderToday(){const log=state.data.daily_logs.find(x=>x.log_date===today())||{};const st=weekStats();return `${renderTodayLinks()}${pageHead('Точка действия','Сегодня — один понятный шаг.','Сначала главное действие для дохода. Затем здоровье, язык и время с семьёй.',`<button class="button" data-action="new-task">${icon('plus')} Задача</button>`)}<div class="grid cols2"><section class="card highlight"><div class="spread mb14"><h2>${state.lowEnergy?'Минимум на сложный день':'Три главных действия'}</h2><button class="button small ghost" data-action="low-energy">${state.lowEnergy?'Обычный режим':'Мало энергии?'}</button></div>${state.lowEnergy?`<div class="low-energy-card"><b>10 минут. Один шаг.</b><p>Напиши одному потенциальному клиенту или сделай первый маленький шаг. Это не заменяет полноценные цели, но помогает вернуться к действию.</p></div>`:todayTasks()}<button class="button secondary small mt14" data-action="new-task">Добавить следующее действие</button><div class="callout subtle-callout mt20">В день с низкой энергией достаточно одного короткого действия на 10 минут. Никаких штрафов за отсутствие идеальной серии.</div></section><section class="card"><div class="card-header"><h2>Короткий чек-ин</h2><span class="pill gray">${ruDate(today())}</span></div><form data-form="daily" class="stack"><div class="form-grid">${field('sleep_hours','Сон, часов','number',log.sleep_hours??'','min="0" max="24" step="0.1"')}${selectField('energy','Энергия (1–10)',[...Array(10)].map((_,i)=>[i+1,`${i+1}/10`]),String(normalizedEnergy(log)||6))}${field('focus_min','Сосредоточенная работа, мин','number',log.focus_min??0,'min="0" max="1440"')}${field('social_min','Соцсети, мин','number',log.social_min??0,'min="0" max="1440"')}${field('exercise_min','Спорт / движение, мин','number',log.exercise_min??0,'min="0" max="1440"')}${field('english_min','Английский, мин · цель 60','number',log.english_min??0,'min="0" max="1440"')}${field('learning_min','Видео или книга, мин · цель 60','number',log.learning_min??0,'min="0" max="1440"')}${selectField('learning_kind','Формат обучения',[['video','Видео / курс'],['book','Книга / аудиокнига'],['practice','Практика / конспект']],log.learning_kind||'video')}${field('family_min','Качественное время с семьёй, мин','number',log.family_min??0,'min="0" max="1440"')}${selectField('mood','Настроение',[['1','1 · тяжело'],['2','2 · ниже среднего'],['3','3 · нормально'],['4','4 · хорошо'],['5','5 · отлично']],String(log.mood||3))}</div>${field('learning_title','Что изучал? Название / глава','text',log.learning_title||'','placeholder="Например: книга, глава 3"')}${field('learning_insight','Одно применимое знание','textarea',log.learning_insight||'','placeholder="Что я изменю на практике?"')}${field('one_action','Что сегодня приблизило к цели?','textarea',log.one_action||'','placeholder="Даже маленькое конкретное действие"')}${field('obstacle','Что мешало?','textarea',log.obstacle||'','placeholder="Без самообвинений: наблюдение → корректировка"')}<button class="button" type="submit">${icon('check')} Сохранить день</button></form></section></div><section class="card mt20"><div class="card-header"><h2>Твой текущий ритм</h2><span class="pill gray">7 дней</span></div><div class="grid cols4">${kpi('Дней с записью',String(st.logs),'из последних семи','calendar')}${kpi('Работа в фокусе',String(st.focus)+' мин','за неделю','sun')}${kpi('Английский',String(st.english)+' мин','за неделю','book')}${kpi('Время с семьёй',String(st.family)+' мин','за неделю','users')}</div></section>`}
function renderGoals(){const gs=[...state.data.goals].sort((a,b)=>String(a.deadline||'9999').localeCompare(String(b.deadline||'9999')));const buckets=[['90','Ближайшие 90 дней','Измеримые результаты, которые влияют на каждую неделю'],['year','Горизонт 12 месяцев','Стабильность вместо хаотичных рывков'],['long','Долгосрочная карта','Большие мечты, не ежедневное давление']];return `${pageHead('От мечты к действию','Твоя карта целей','Для каждой цели есть исходная точка, числовой ориентир, срок и следующий шаг.',`<button class="button" data-action="new-goal">${icon('plus')} Добавить цель</button>`)}<div class="card highlight mb14"><div class="spread"><div><div class="eyebrow">Фокус этой недели</div><h2 class="mt8">${e(state.profile?.focus_title||'Проверить спрос и получить первый заказ')}</h2></div><span class="pill">Один проект за раз</span></div></div><div class="card mt20 roadmap-card"><div class="card-header"><div><div class="eyebrow">ДОРОЖНАЯ КАРТА · ДО 90 ДНЕЙ</div><h2 class="mt8">Промежуточные контрольные точки</h2></div><span class="pill gray">Это ориентиры, не автоматические достижения</span></div><div class="roadmap-grid">${[['Дни 1–14','Одна услуга','Выбрать конкретную аудиторию, написать предложение, получить первые ответы'],['Дни 15–30','Первый клиент','Дойти до разговоров с покупателями и первого оплаченного теста'],['Дни 31–60','Повторяемость','Повторять рабочий сценарий продаж, выйти на €500–1 000/мес'],['Дни 61–90','€1 500 / мес','Получать заказы по повторяемой схеме и вести учёт оплаты']].map(([time,label,detail],i)=>`<div class="roadmap-stop"><div class="roadmap-num">0${i+1}</div><div class="micro muted">${time}</div><h3 class="mt8">${label}</h3><p>${detail}</p></div>`).join('')}</div><p class="footnote mt14">Прохождение 14 или 30 дней само по себе не означает выполнение этапа — отмечай факты и проверяй оплаты.</p></div>${buckets.map(([h,title,sub])=>`<h2 class="section-title">${title}</h2><p class="muted small mb14">${sub}</p><div class="grid cols2">${gs.filter(g=>g.horizon===h).length?gs.filter(g=>g.horizon===h).map(g=>`<div class="card soft">${goalCards([g])}</div>`).join(''):'<div class="card"><div class="empty">Здесь пока нет активных целей.</div></div>'}</div>`).join('')}<div class="card mt20"><div class="card-header"><h2>Как мы измеряем прогресс</h2></div><div class="grid cols3"><div><span class="pill">Результат</span><p class="small muted mt8">Доход, долг, количество оплаченных заказов</p></div><div><span class="pill gray">Действия</span><p class="small muted mt8">Контакты с клиентами, практика английского, тренировки</p></div><div><span class="pill gold">Качество жизни</span><p class="small muted mt8">Энергия, сон, время с семьёй, отсутствие перегруза</p></div></div></div>`}
function renderFinance(){const arr=[...state.data.finance_entries].sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date)));const mo=monthKey(today()),income=monthIncome(mo),expense=arr.filter(x=>x.kind==='expense'&&monthKey(x.entry_date)===mo).reduce((s,x)=>s+num(x.amount_eur),0),repay=arr.filter(x=>x.kind==='debt_payment'&&monthKey(x.entry_date)===mo).reduce((s,x)=>s+num(x.amount_eur),0);return `${pageHead('Деньги без иллюзий','Финансовая панель','Фактические поступления, расходы, долг и платежи — отдельно от планов.',`<button class="button" data-action="new-finance">${icon('plus')} Добавить операцию</button>`)}<div class="grid cols4">${kpi('Доход за месяц',money(income),'Только подтверждённые поступления','wallet','accent')}${kpi('Расходы за месяц',money(expense),'Внесённые расходы','wallet')}${kpi('Текущий долг',money(currentDebt()),'Баланс по последнему снимку','target','warn')}${kpi('Резерв 20%',money(monthReserve()),`Нужно перевести ${money(income*.2)} · реально ${money(monthReserve())}`,'check')}</div><div class="card reserve-feature mt20"><div class="spread"><div><div class="eyebrow">ПРАВИЛО ФИНАНСОВОЙ ЗАЩИТЫ</div><h2 class="mt8">20% каждого поступления — на отдельный резервный счёт</h2><p class="small muted mt8">План за месяц: <b>${money(income*.2)}</b> · отмечено переводов: <b>${money(monthReserve())}</b> · накоплено по записям: <b>${money(reserveBalance())}</b></p></div><div class="reserve-mark">20%</div></div><div class="progress-track mt14"><div class="progress-fill" style="width:${income>0?clamp(monthReserve()/(income*.2)*100):0}%"></div></div><p class="footnote mt14">MONTBLANC рассчитывает сумму и отмечает перевод, но не отправляет деньги в банк. При нехватке средств на необходимые расходы семьи лучше пересмотреть доступную сумму, чем накапливать дорогие просрочки.</p></div><div class="grid cols2 mt20"><div class="card"><div class="card-header"><h2>Доход · последние 6 месяцев</h2><span class="pill gray">Цель: ${money(state.profile?.goal_90||1500)}</span></div>${incomeChart()}</div><div class="card"><div class="card-header"><h2>Финансовые этапы</h2></div><div class="timeline">${[['01','Первый платёж'],['02','€500/мес'],['03','€1 500/мес'],['04','€2 500/мес']].map(([n,label])=>`<div class="timeline-item"><div class="timeline-circle">${n}</div><div class="micro muted">${e(label)}</div></div>`).join('')}</div><hr class="divider"/><div class="callout subtle-callout">Долг уменьшается в аналитике только после записи фактического остатка. Одни лишь платежи не гарантируют снижение долга: могут быть проценты и комиссии.</div><p class="small muted mt14">Пока неизвестны обязательные расходы семьи и условия кредитов, система не строит фиктивный график полного погашения.</p></div></div><div class="card mt20"><div class="card-header"><h2>Журнал денег</h2><span class="pill gray">${arr.length} записей</span></div>${arr.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Тип</th><th>Сумма</th><th>Комментарий</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td>${ruDate(x.entry_date)}</td><td>${e(({income:'Доход',expense:'Расход',debt_balance:'Остаток долга',debt_payment:'Платёж по долгу'})[x.kind]||x.kind)}</td><td>${money(x.amount_eur)}</td><td>${e(x.description||'—')}</td><td><button class="button small ghost" data-action="delete" data-table="finance_entries" data-id="${e(x.id)}">Удалить</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Записей ещё нет. Начни с первого фактического поступления или обновления остатка долга.</div>'}</div>`}
function renderHabits(){const logs=state.data.daily_logs;const labels=lastDays(14);const st=weekStats();const graph=(key)=>svgChart(labels.map(d=>logs.find(x=>x.log_date===d)?.[key]??null),labels.map(d=>d.slice(8)),{target:key==='social_min'?60:null});return `${pageHead('Энергия — ресурс','Здоровье и привычки','Сон, тело, фокус и экранное время. Мягкий контроль без наказаний.',`<button class="button" data-page="today">${icon('plus')} Заполнить сегодняшний день</button>`)}<div class="grid cols4">${kpi('Сон за 7 дней',st.sleepAverage===null?'—':st.sleepAverage.toFixed(1)+' ч','Среднее только по записям','heart')}${kpi('Энергия',st.energyAverage===null?'—':st.energyAverage.toFixed(1)+'/5','Самооценка, не диагноз','sun')}${kpi('Тренировок',String(st.sport),'Ориентир: 3 в неделю','heart')}${kpi('Соцсети',st.socialAverage===null?'—':st.socialAverage+' мин','Ориентир: ≤60 минут в день','chart')}</div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Время в соцсетях</h2><span class="pill gray">14 дней</span></div>${graph('social_min')}</section><section class="card"><div class="card-header"><h2>Сосредоточенная работа</h2><span class="pill gray">14 дней</span></div>${graph('focus_min')}</section><section class="card"><div class="card-header"><h2>Сон</h2><span class="pill gray">14 дней</span></div>${svgChart(labels.map(d=>logs.find(x=>x.log_date===d)?.sleep_hours??null),labels.map(d=>d.slice(8)),{target:7})}</section><section class="card"><div class="card-header"><h2>Энергия (1–5)</h2><span class="pill gray">14 дней</span></div>${svgChart(labels.map(d=>normalizedEnergy(logs.find(x=>x.log_date===d))),labels.map(d=>d.slice(8)),{max:5})}</section></div><div class="card mt20"><div class="card-header"><h2>Привычки, которые работают на тебя</h2></div><div class="grid cols3"><div><div class="eyebrow">Тело</div><h3 class="mt8">3 тренировки в неделю</h3><p class="small muted mt8">Начать с посильных 20–40 минут. Увеличивать нагрузку постепенно.</p></div><div><div class="eyebrow">Английский</div><h3 class="mt8">20 минут ежедневно</h3><p class="small muted mt8">Регулярная практика важнее попытки каждый раз заниматься идеально.</p></div><div><div class="eyebrow">Семья</div><h3 class="mt8">Время без экрана</h3><p class="small muted mt8">Короткое осознанное общение каждый день, без превращения семьи в KPI.</p></div></div></div>`}
function renderIdeas(){const ideas=[...state.data.ideas].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));const filtered=state.filter==='all'?ideas:ideas.filter(x=>x.status===state.filter);return `${pageHead('Парковка идей','Идеи — не обязательства.','Записывай, комментируй и оценивай. Новая идея не отменяет выбранный 14-дневный фокус.',`<button class="button" data-action="new-idea">${icon('plus')} Записать идею</button>`)}<div class="card highlight mb14"><div class="spread"><div><h2>Правило: одна активная проверка</h2><p class="small muted mt8">Остальные идеи лежат здесь до еженедельного обзора.</p></div><span class="pill">Без переключений</span></div></div><div class="seg mb14" style="width:max-content;max-width:100%;overflow:auto">${[['all','Все'],['inbox','Новые'],['testing','Проверяю'],['parked','Позже'],['discarded','Неактуально']].map(([v,t])=>`<button class="${state.filter===v?'selected':''}" data-action="filter-ideas" data-value="${v}">${t}</button>`).join('')}</div><div class="grid cols2">${filtered.length?filtered.map(x=>{const ct=state.data.idea_comments.filter(z=>z.idea_id===x.id).length;return `<div class="idea-card"><div class="spread"><span class="pill ${x.status==='testing'?'':'gray'}">${e(({inbox:'Новая',testing:'На проверке',parked:'В запасе',discarded:'Архив'})[x.status]||x.status)}</span><span class="small muted">${ruDate((x.created_at||'').slice(0,10))}</span></div><h3>${e(x.title)}</h3><p>${e(x.description||'Без описания').slice(0,200)}${String(x.description||'').length>200?'…':''}</p><div class="spread mt14"><span class="small muted">${ct} комментариев</span><button class="button small secondary" data-action="view-idea" data-id="${e(x.id)}">Открыть ${icon('arrow')}</button></div></div>`}).join(''):'<div class="empty">Пока нет идей в этом разделе.</div>'}</div>`}
function renderJournal(){const entries=[...state.data.journal_entries].sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date)));return `${pageHead('Мысли и наблюдения','Личный дневник','Фиксируй опыт, решения, сомнения и то, что реально сработало.',`<button class="button" data-action="new-journal">${icon('plus')} Новая запись</button>`)}<div class="grid cols2"><section class="card highlight"><h2 class="mb14">О чём стоит написать сегодня</h2><div class="plan-step"><span class="step-number">1</span><div><h3>Что сегодня получилось?</h3><p>Даже одно маленькое полезное действие.</p></div></div><div class="plan-step"><span class="step-number">2</span><div><h3>Где я потерял время или энергию?</h3><p>Описать причину, а не критиковать себя.</p></div></div><div class="plan-step"><span class="step-number">3</span><div><h3>Что я сделаю завтра иначе?</h3><p>Один конкретный эксперимент вместо списка обещаний.</p></div></div></section><section class="card"><div class="card-header"><h2>История записей</h2><span class="pill gray">${entries.length}</span></div>${entries.length?entries.map(x=>`<div class="journal-item"><div class="small muted">${ruDate(x.entry_date)}</div><h3>${e(x.title||'Запись')}</h3><p>${e(x.content||'')}</p><div class="row mt8"><button class="button small ghost" data-action="edit-journal" data-id="${e(x.id)}">Изменить</button><button class="button small ghost" data-action="delete" data-table="journal_entries" data-id="${e(x.id)}">Удалить</button></div></div>`).join(''):'<div class="empty">Первая запись появится здесь. Не обязательно писать каждый день.</div>'}</section></div>`}
function renderReview(){const st=weekStats(),todayLog=state.data.daily_logs.find(x=>x.log_date===today());const recent=state.data.weekly_reviews.slice().sort((a,b)=>String(b.week_end).localeCompare(String(a.week_end)));const weekStart=plusDays(today(),-6);const review=recent.find(x=>x.week_end===today())||{};return `${pageHead('Результаты вместо эмоций','Недельный обзор','Раз в неделю смотри на действия, деньги и самочувствие — затем корректируй следующий шаг.',`<button class="button" data-page="today">${icon('sun')} Перейти к сегодняшнему дню</button>`)}<div class="grid cols4">${kpi('Заполнено дней',`${st.logs}/7`,'Регулярность наблюдений','calendar')}${kpi('Выполнено задач',String(st.completed),'За последние 7 дней','check')}${kpi('Фокус',`${st.focus} мин`,'Сосредоточенная работа','target')}${kpi('Тренировки',String(st.sport),'Длительностью ≥20 минут','heart')}</div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Результат и выводы</h2><span class="pill gray">${ruDate(weekStart)} — ${ruDate(today())}</span></div><form data-form="review" class="stack">${field('wins','3 факта, которые показывают прогресс','textarea',review.wins||'','placeholder="Конкретные действия или результаты"')}${field('blockers','Что мешало на этой неделе?','textarea',review.blockers||'','placeholder="Например: работа без продаж, соцсети, нерегулярный сон"')}${field('adjustment','Что меняю на следующей неделе?','textarea',review.adjustment||'','placeholder="Одно изменение, которое можно проверить"')}${field('next_week_focus','Главный фокус на следующую неделю','textarea',review.next_week_focus||'','placeholder="Только один главный приоритет"')}<button class="button" type="submit">${icon('check')} Сохранить недельный разбор</button></form></section><section class="card"><div class="card-header"><h2>Дневные записи за 7 дней</h2></div>${lastDays(7).map(d=>{const l=state.data.daily_logs.find(x=>x.log_date===d);return `<div class="spread" style="border-top:1px solid var(--edge);padding:14px 0"><span class="small">${ruDate(d)}</span><div class="row"><span class="pill gray">${l?'Фокус '+num(l.focus_min)+' мин':'Нет записи'}</span><span class="pill ${l&&num(l.energy)>=4?'':'gray'}">${l?'Энергия '+num(l.energy)+'/5':'—'}</span></div></div>`}).join('')}<div class="callout subtle-callout mt14">Если неделя была сложной, цель — не «догонять», а выбрать следующий достижимый шаг. Полезно искать причины, а не виноватых.</div></section></div>${recent.length?`<h2 class="section-title">Архив обзоров</h2><div class="grid cols2">${recent.map(x=>`<div class="card"><div class="small muted">Неделя до ${ruDate(x.week_end)}</div><h3 class="mt8">Что сработало</h3><p class="small note-text mt8">${e(x.wins)}</p><h3 class="mt14">Изменение</h3><p class="small note-text mt8 muted">${e(x.adjustment)}</p></div>`).join('')}</div>`:''}${renderInsights()}`}
function renderSettings(){const p=state.profile||{};return `${pageHead('Под твоим контролем','Настройки и приватность','Здесь меняются базовые цифры, фокус и правила хранения данных.')}<div class="grid cols2"><section class="card"><div class="card-header"><h2>Моя точка А и цели</h2></div><form data-form="settings" class="stack"><div class="form-grid">${field('income_baseline','Стабильный доход в начале, €/мес','number',p.income_baseline??0,'min="0" step="0.01" required')}${field('debt_baseline','Долг в начале, €','number',p.debt_baseline??0,'min="0" step="0.01" required')}${field('goal_90','Цель через 90 дней, €/мес','number',p.goal_90??1500,'min="0" required')}${field('goal_year','Цель через 12 месяцев, €/мес','number',p.goal_year??2500,'min="0" required')}${field('social_baseline','Соцсети в начале, мин/день','number',p.social_baseline??120,'min="0" required')}${field('sport_baseline','Спорт в начале, раз/нед','number',p.sport_baseline??1,'min="0" required')}</div>${field('focus_title','Один главный фокус на ближайшие 14 дней','textarea',p.focus_title||'')}${field('why_text','Моя причина двигаться вперёд','textarea',p.why_text||'')}${field('vision_text','Жизнь, которую хочу построить','textarea',p.vision_text||'')}<button class="button" type="submit">${icon('check')} Сохранить настройки</button></form></section><section class="card"><div class="card-header"><h2>Доступ и данные</h2><span class="pill">${state.demo?'DEMO':icon('lock')+' PRIVATE'}</span></div><div class="safe">${state.demo?'Это демонстрационный режим. Записи исчезнут после перезагрузки.':state.local?'🔒 Записи зашифрованы на этом устройстве. Нет автоматической синхронизации iPhone ↔ Mac. Делай резервные копии регулярно.':'Личные записи в Supabase защищены авторизацией и RLS.'}</div><h3 class="mt20">Резервная копия</h3><p class="small muted mt8">${state.local?'Скачай зашифрованный архив. Для восстановления понадобится пароль.':'Экспорт содержит личные записи без шифрования — храни только в безопасном месте.'}</p><button class="button secondary mt14" data-action="export">${icon('download')} ${state.local?'Скачать шифрованный архив':'Скачать JSON'}</button>${state.local?`<button class="button ghost mt14" data-action="local-lock">${icon('lock')} Заблокировать дневник</button>`:''}<hr class="divider"/><h3 class="mt20">Приложение на телефоне</h3><p class="small muted mt8">На iPhone: открой опубликованную HTTPS-ссылку в Safari → Поделиться → На экран «Домой». На Android: нажми кнопку ниже или используй меню Chrome «Установить приложение».</p><button class="button secondary mt14" data-action="install-app">${icon('download')} Установить на устройство</button><p class="small muted mt8">Для установки нужен опубликованный HTTPS-адрес. Локальный HTML-файл не устанавливается как PWA. Offline-доступ сохраняет только код приложения; личные записи хранятся отдельно в локальном зашифрованном хранилище или защищённой базе.</p><h3 class="mt20">Важная граница приватности</h3><p class="small muted mt8">Публикуемый веб-интерфейс может быть открыт для просмотра до входа. В локальном режиме записи шифруются на устройстве; в облачном — защищаются авторизацией и RLS. Страница входа может быть публичной, хотя записи закрыты.</p><hr class="divider"/>${state.demo?`<button class="button ghost" data-action="leave-demo">Выйти из демо</button>`:`<button class="button ghost" data-action="logout">${icon('logout')} Выйти из аккаунта</button>`}</section></div>`}
function renderLearning(){const logs=logBetween(plusDays(today(),-29),today()),days=lastDays(30),total=sumOf(logs,'learning_min'),hits=logs.filter(x=>num(x.learning_min)>=60).length,books=logs.filter(x=>x.learning_kind==='book'),vid=logs.filter(x=>x.learning_kind==='video'),notes=logs.filter(x=>String(x.learning_title||'').trim());return `${pageHead('60 МИНУТ КАЖДЫЙ ДЕНЬ','Знания, которые меняют действия.','Книга, лекция, курс или практическое видео. Каждый день записывай одну применимую мысль.',`<button class="button" data-page="today">Записать обучение ${icon('plus')}</button>`)}<section class="learning-hero"><div><div class="eyebrow">ИНТЕЛЛЕКТУАЛЬНЫЙ КАПИТАЛ</div><h2 class="mt8">1 час в день × 30 дней = 30 часов осознанного обучения.</h2><p>Важно не просто смотреть и читать, а фиксировать один вывод, который применишь завтра.</p></div>${ring(clamp(total/(30*60)*100),'',''+Math.round(total/60*10)/10+' ч',{size:150,color:'#856af4'})}</section><div class="grid cols4 mt20">${kpi('Часы за 30 дней',(total/60).toFixed(1),'План: 30 часов','book')}${kpi('Дней ≥60 минут',String(hits),'За последние 30 дней','check')}${kpi('Книги / чтение',String(books.length),'Дневных записей','book')}${kpi('Видео / курсы',String(vid.length),'Дневных записей','chart')}</div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Обучение · последние 30 дней</h2><span class="pill gray">Пунктир — 60 мин</span></div>${svgChart(days.map(d=>logs.find(l=>l.log_date===d)?.learning_min??null),days.map(d=>d.slice(5)),{target:60})}</section><section class="card"><div class="card-header"><h2>Принцип 60 / 10</h2><span class="pill gray">Практика важнее количества</span></div><div class="plan-step"><span class="step-number">01</span><div><h3>Выбери один материал</h3><p>Книга или видео на тему, полезную для твоих целей.</p></div></div><div class="plan-step"><span class="step-number">02</span><div><h3>60 минут без переключений</h3><p>Только этот материал, телефон вне зоны внимания.</p></div></div><div class="plan-step"><span class="step-number">03</span><div><h3>10 минут на применение</h3><p>Запиши один вывод и используй в течение суток.</p></div></div></section></div><div class="card mt20"><div class="card-header"><h2>История обучения</h2><span class="pill gray">${notes.length} записей за 30 дней</span></div>${notes.length?notes.sort((a,b)=>b.log_date.localeCompare(a.log_date)).map(l=>`<div class="study-entry"><div class="spread"><strong>${e(l.learning_title)}</strong><span class="small muted">${ruDate(l.log_date)} · ${num(l.learning_min)} мин</span></div><p>${e(l.learning_insight||'Вывод пока не записан')}</p></div>`).join(''):'<div class="empty">Запиши первую книгу или видео в разделе «Сегодня».</div>'}</div>`}
function renderEnglish(){const start=state.profile?.started_at||today(),end=addMonths(start,4),left=Math.max(0,deltaDays(today(),end)),total=Math.max(1,deltaDays(start,end)),daysElapsed=Math.max(0,deltaDays(start,today())),percent=clamp(daysElapsed/total*100),logs=logBetween(plusDays(today(),-29),today()),mins=sumOf(logs,'english_min'),checks=state.data.skill_checks||[],skills=[['speaking','Говорение'],['listening','Аудирование'],['reading','Чтение'],['writing','Письмо']],levels={A1:0,A2:50,B1:100};const lastSkill=s=>checks.filter(x=>x.skill===s).sort((a,b)=>String(b.assessed_on).localeCompare(String(a.assessed_on)))[0];return `${pageHead('ЯЗЫКОВОЙ МАРШРУТ','A1 → B1 за 4 месяца','Амбициозный план. Минуты практики показывают усилия, уровень подтверждаем контрольными заданиями и речью.',`<button class="button" data-action="skill-check">${icon('check')} Отметить проверку</button>`)}<section class="english-hero"><div><div class="eyebrow">ТВОЯ ЦЕЛЬ · B1</div><h2 class="mt8">Говорить увереннее. Понимать больше. Действовать свободнее.</h2><p>Старт A1 · контрольная дата ${ruDate(end)}. До неё ${left} дней; текущий прогресс по календарю ${Math.round(percent)}% — это не оценка языка.</p></div><div class="language-letters">A1 <span>${icon('arrow')}</span> B1</div></section><div class="grid cols4 mt20">${kpi('Практика за 30 дней',(mins/60).toFixed(1)+' ч','План: 30 часов','book')}${kpi('Дней ≥60 мин',String(logs.filter(x=>num(x.english_min)>=60).length),'За 30 дней','check')}${kpi('До контрольной даты',left+' дн','B1 не гарантируется календарём','calendar')}${kpi('Подтверждено B1',String(skills.filter(([k])=>lastSkill(k)?.level==='B1').length)+'/4','Навыка по записанным проверкам','target')}</div><div class="card mt20"><div class="card-header"><h2>4 навыка · только по проверкам</h2><span class="pill gray">Не подменяем уровень часами</span></div><div class="grid cols2">${skills.map(([k,name])=>{const c=lastSkill(k),pct=levels[c?.level]??0;return `<div class="skill-meter"><div class="spread"><strong>${name}</strong><span class="pill gray">${c?e(c.level):'Не проверено'}</span></div><div class="progress-track mt14"><div class="progress-fill" style="width:${pct}%"></div></div><p class="micro muted mt8">${c?`Последняя проверка: ${ruDate(c.assessed_on)} · ${e(c.evidence||'без примера')}`:'Сохрани результат реального занятия или мини-теста'}</p></div>`}).join('')}</div></div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Минуты английского · 30 дней</h2><span class="pill gray">Цель 60 мин/день</span></div>${svgChart(lastDays(30).map(d=>logs.find(x=>x.log_date===d)?.english_min??null),lastDays(30).map(d=>d.slice(5)),{target:60})}</section><section class="card"><div class="card-header"><h2>Маршрут по месяцам</h2><span class="pill gray">Контроль каждые 4 недели</span></div>${[['Месяц 1','A1 → A2','Уверенные базовые фразы, прошедшее и будущее, разговор 3–5 минут'],['Месяц 2','A2','Ежедневные ситуации, аудирование с замедлением, диалог 5–8 минут'],['Месяц 3','A2 → B1','Объяснять мнение, вести разговор 10 минут, понимать адаптированные материалы'],['Месяц 4','Проверка B1','Сдать пробный тест по всем навыкам и разговор 10–15 минут']].map(([m,l,d],i)=>`<div class="plan-step"><span class="step-number">0${i+1}</span><div><div class="small muted">${m} · ориентир</div><h3 class="mt8">${l}</h3><p>${d}</p></div></div>`).join('')}</section></div><div class="card mt20"><h2>Ежедневная практика · 60 минут</h2><div class="grid cols4 mt14">${[['15 мин','Говорить вслух'],['15 мин','Аудирование'],['15 мин','Слова + грамматика'],['15 мин','Чтение или письмо']].map(([n,t])=>`<div class="mini-step"><b>${n}</b><span>${t}</span></div>`).join('')}</div><p class="footnote mt14">Если день тяжёлый, 15–20 минут лучше полного отказа. Для уверенного B1 за четыре месяца обычно требуется и системность, и обратная связь от преподавателя; график не гарантирует результат.</p></div>`}
function selectedMonth(){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+(state.monthOffset||0));return localDate(d).slice(0,7)}
function monthlyPayload(month){const [yy,mm]=month.split('-').map(Number);const start=`${month}-01`,end=localDate(new Date(yy,mm,0)),logs=logBetween(start,end);const incomes=state.data.finance_entries.filter(x=>x.kind==='income'&&monthKey(x.entry_date)===month);const expenses=state.data.finance_entries.filter(x=>x.kind==='expense'&&monthKey(x.entry_date)===month);const tasks=state.data.tasks.filter(x=>x.task_date>=start&&x.task_date<=end);const daysInMonth=new Date(yy,mm,0).getDate();return {month,days_in_month:daysInMonth,days_elapsed:month===monthKey(today())?Math.min(daysInMonth,Number(today().slice(8))):month<monthKey(today())?daysInMonth:0,days_logged:logs.length,earned_eur:sumOf(incomes,'amount_eur'),income_target_eur:num(state.profile?.goal_90||1500),spending_eur:sumOf(expenses,'amount_eur'),reserve_target_eur:sumOf(incomes,'amount_eur')*.2,reserve_actual_eur:monthReserve(month),debt_snapshot_eur:currentDebt(),study_hours:Math.round(sumOf(logs,'learning_min')/6)/10,english_hours:Math.round(sumOf(logs,'english_min')/6)/10,study_days_60min:logs.filter(l=>num(l.learning_min)>=60).length,english_days_60min:logs.filter(l=>num(l.english_min)>=60).length,exercise_days:logs.filter(l=>num(l.exercise_min)>=20).length,focus_hours:Math.round(sumOf(logs,'focus_min')/6)/10,average_social_minutes:logs.length?Math.round(avg(logs.map(l=>l.social_min))):null,average_energy:logs.some(l=>l.energy!=null)?Math.round(avg(logs.filter(l=>l.energy!=null).map(normalizedEnergy))*10)/10:null,tasks_total:tasks.length,tasks_completed:tasks.filter(t=>t.completed).length,sales_contacts:sumOf(logs,'sales_contacts'),sales_replies:sumOf(logs,'sales_replies'),sales_calls:sumOf(logs,'sales_calls'),sales_offers:sumOf(logs,'sales_offers'),sales_paid:sumOf(logs,'sales_paid'),notes:'Отсутствие записи не означает ноль. Резерв отмечается вручную. Долг — последний снимок, без прогнозирования.'}}
function localAnalysis(r){const n=r.days_logged,coverage=Math.round(n/Math.max(1,r.days_elapsed)*100),a=[];a.push({level:coverage<50?'warn':'good',title:'Качество данных',body:`Заполнено ${n} из ${r.days_elapsed} прошедших дней (${coverage}%). ${coverage<50?'Недостаточно данных для уверенных выводов о привычках.':'Есть база для сравнения привычек.'}`});if(r.earned_eur<r.income_target_eur)a.push({level:'warn',title:'Финансовый результат',body:`Получено ${money(r.earned_eur)} против цели ${money(r.income_target_eur)}. Следующий шаг — измерять контакты, разговоры и оплаченные заказы, не только часы работы.`});else a.push({level:'good',title:'Финансовый результат',body:`Целевой месячный доход достигнут: ${money(r.earned_eur)}. Проверь устойчивость источника и повторяемость заказов.`});if(r.earned_eur>0){a.push({level:r.reserve_actual_eur>=r.reserve_target_eur?'good':'warn',title:'Резерв 20%',body:`План ${money(r.reserve_target_eur)}; внесено ${money(r.reserve_actual_eur)}. ${r.reserve_actual_eur<r.reserve_target_eur?'Проверь возможность перевода с учётом обязательных расходов и долгов.':'План на этот месяц выполнен.'}`})}else a.push({level:'neutral',title:'Резерв 20%',body:'Пока нет записанного дохода. Не считаем отсутствие накоплений провалом.'});if(r.sales_contacts===0)a.push({level:'warn',title:'Воронка продаж',body:'В этом месяце не записано контактов с покупателями. Начни с 5–10 адресных сообщений и фиксируй ответы.'});else if(r.sales_contacts>=20&&r.sales_replies===0)a.push({level:'warn',title:'Низкий отклик',body:`${r.sales_contacts} контактов и 0 ответов по записям. Уточни сегмент и первое сообщение.`});else if(r.sales_replies>=5&&r.sales_offers===0)a.push({level:'warn',title:'От общения к офферу',body:`${r.sales_replies} ответов, но предложений не отмечено. Сформулируй одно конкретное платное предложение.`});else a.push({level:'neutral',title:'Воронка продаж',body:`Контакты ${r.sales_contacts}, ответы ${r.sales_replies}, предложения ${r.sales_offers}, оплаты ${r.sales_paid}. Проверяй, на каком этапе теряются люди.`});a.push({level:r.study_hours>=20?'good':'neutral',title:'Обучение',body:`${r.study_hours} ч за месяц, ${r.study_days_60min} дней с 60+ минутами. Смотри не только часы, но и записанные применённые идеи.`});a.push({level:r.english_hours>=20?'good':'neutral',title:'Английский',body:`${r.english_hours} ч практики. Уровень A1/B1 определяется отдельными проверками речи, чтения, письма и аудирования.`});if(coverage>30&&r.average_social_minutes!==null)a.push({level:r.average_social_minutes<=60?'good':'warn',title:'Время в соцсетях',body:`В записанные дни в среднем ${r.average_social_minutes} мин/день. Попробуй ограничить ленту перед первым рабочим блоком.`});return a}
function renderMonthly(){const m=selectedMonth(),p=monthlyPayload(m),checks=localAnalysis(p),stored=(state.data.ai_reports||[]).filter(x=>x.month_key===m).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0];return `${pageHead('РЕЗУЛЬТАТЫ В ЦИФРАХ','Месячный разбор прогресса','Где двигаешься, где отстаёшь и что менять на следующей неделе. Никаких выдуманных оценок.',`<button class="button" data-page="today">Заполнить сегодняшний день</button>`)}<div class="month-nav"><button class="button ghost small" data-action="month-prev">← Предыдущий</button><strong>${new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(m+'-01T12:00:00'))}</strong><button class="button ghost small" data-action="month-next" ${(state.monthOffset||0)>=0?'disabled':''}>Следующий →</button></div><div class="grid cols4 mt20">${kpi('Доход',money(p.earned_eur),`Ориентир ${money(p.income_target_eur)}`,'wallet')}${kpi('Фокус',p.focus_hours+' ч','Глубокая работа','sun')}${kpi('Учёба',p.study_hours+' ч','60 мин ежедневно · цель','book')}${kpi('Английский',p.english_hours+' ч','B1 проверяется отдельно','book')}</div><div class="card mt20"><div class="spread"><h2>Реальные продажи за месяц</h2><span class="pill gray">Контакты → ответы → офферы → оплаты</span></div><div class="sales-kpis">${[['Контакты',p.sales_contacts],['Ответы',p.sales_replies],['Предложения',p.sales_offers],['Оплаты',p.sales_paid]].map(x=>`<div><b>${x[1]}</b><span>${e(x[0])}</span></div>`).join('')}</div><p class="small muted mt8">Зафиксированы действия за ${p.days_logged} дней. Это не подтверждение дохода — денежные поступления учитываются отдельно.</p></div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Динамика обучения</h2><span class="pill gray">Последние дни месяца</span></div>${(()=>{const [yy,mm]=m.split('-').map(Number);const len=new Date(yy,mm,0).getDate();const dates=Array.from({length:len},(_,i)=>m+'-'+String(i+1).padStart(2,'0'));return svgChart(dates.map(d=>state.data.daily_logs.find(l=>l.log_date===d)?.learning_min??null),dates.map(d=>d.slice(8)),{target:60})})()}</section><section class="card"><div class="card-header"><h2>Честная диагностика</h2><span class="pill gray">${p.days_logged}/${p.days_elapsed} прошедших дней</span></div>${checks.map(c=>`<div class="insight-row ${c.level}"><span class="insight-dot"></span><div><strong>${e(c.title)}</strong><p>${e(c.body)}</p></div></div>`).join('')}</section></div><section class="card mt20 ai-panel"><div class="spread ai-heading"><div><div class="eyebrow">LIFE COACH · CHATGPT</div><h2 class="mt8">Аналитика и план коррекции</h2><p class="small muted mt8">В автономном режиме можно самостоятельно отправить в ChatGPT отчёт после проверки личных заметок.</p></div><span class="ai-star">✦</span></div><div class="row mt20 ai-buttons"><button class="button" data-action="generate-ai" ${(state.demo||state.local)?'disabled title="AI доступен после подключения облачной базы и API"':''}>${icon('spark')} ${stored?'Обновить анализ ChatGPT':'Сформировать анализ ChatGPT'}</button><button class="button secondary" data-action="copy-month">${icon('download')} Скопировать показатели для ChatGPT</button></div><p class="footnote mt14">Ручной анализ доступен по кнопке. Автоматическая рассылка в конце месяца пока не настроена. API OpenAI может оплачиваться отдельно от подписки ChatGPT.</p>${stored?`<div class="ai-report mt20"><div class="small muted">Последний AI-отчёт · ${ruDate((stored.created_at||'').slice(0,10))}</div><p class="report-pre">${e(stored.report_text)}</p></div>`:`<div class="empty mt20">AI-отчёта за выбранный месяц пока нет. Ниже — прозрачная диагностика по правилам, не ответ ИИ.</div>`}</section><div class="card mt20"><h2>План на ближайшие 7 дней</h2><div class="grid cols3 mt14"><div class="mini-step"><b>Доход</b><span>Выбрать одно предложение и сделать реальные контакты с клиентами</span></div><div class="mini-step"><b>Навыки</b><span>60 минут обучения и 60 минут английского в обычный день</span></div><div class="mini-step"><b>Энергия</b><span>3 посильные тренировки и отслеживание сна без самокритики</span></div></div></div>${renderInsights()}`}


/* MONTBLANC 6.0 — expedition, behavioral observations and reflections.
   Existing vault key/version, user records and their original tables stay unchanged.
   New fields remain local-only in encrypted payload; no personal data is published. */
const taskIsDone=t=>Boolean(t.completed)||t.status==='done';
const reasonLabel={time:'Не хватило времени',energy:'Мало энергии',distraction:'Отвлечения и соцсети',uncertainty:'Неясно, с чего начать',overload:'Слишком большая задача',fear:'Страх отказа или ошибки',changed:'Обстоятельства изменились',irrelevant:'Потеряла смысл',other:'Другое'};
const taskLabel={finance:'Доход',health:'Тело',growth:'Развитие',family:'Семья',focus:'Фокус',other:'Личное'};
function normalizedEnergy(log){if(!log||log.energy===undefined||log.energy===null)return null;return log.energy_scale===10?clamp(num(log.energy),1,10):clamp(num(log.energy)*2,1,10)}
function atMonday(date=today()){const d=new Date(`${date}T12:00:00`);const wd=(d.getDay()+6)%7;d.setDate(d.getDate()-wd);return localDate(d)}
function monthEnd(date=today()){const d=new Date(`${date}T12:00:00`);return localDate(new Date(d.getFullYear(),d.getMonth()+1,0,12))}
function taskState(t){return taskIsDone(t)?'done':t.status==='cancelled'?'cancelled':t.status==='skipped'?'skipped':'planned'}
function scopeRange(scope){if(scope==='week')return [atMonday(),plusDays(atMonday(),6)];if(scope==='month')return [today().slice(0,7)+'-01',monthEnd()];return [today(),today()]}
function scopedTasks(scope){const tasks=state.data.tasks||[];const [start,end]=scopeRange(scope);
 let filtered=scope==='all'?tasks:scope==='inbox'?tasks.filter(t=>!t.task_date):scope==='today'?tasks.filter(t=>(t.task_date===today() || (t.task_date&&t.task_date<today()&&!taskIsDone(t)&&!['cancelled','skipped'].includes(t.status)))):tasks.filter(t=>(t.task_date>=start&&t.task_date<=end)||(t.task_date&&t.task_date<start&&!taskIsDone(t)&&!['cancelled','skipped'].includes(t.status)));
 return [...filtered].sort((a,b)=>(taskIsDone(a)?1:0)-(taskIsDone(b)?1:0)||Number(Boolean(b.is_main))-Number(Boolean(a.is_main))||(['high','normal','low'].indexOf(a.priority||'normal')-['high','normal','low'].indexOf(b.priority||'normal'))||String(a.task_date||'9999').localeCompare(String(b.task_date||'9999')));
}
function taskCard(t){const completed=taskIsDone(t),status=taskState(t),muted=['cancelled','skipped'].includes(status),sub=t.subtasks||[];
 return `<article class="mb-task ${completed?'is-done':''} ${muted?'is-muted':''}"><div class="mb-task-row"><button class="mb-task-check ${completed?'checked':''}" data-action="toggle-task" data-id="${e(t.id)}" aria-label="${completed?'Вернуть задачу':'Отметить выполненной'}">${completed?icon('check'):''}</button><div class="mb-task-body"><div class="mb-task-name">${t.is_main?'<span class="priority-star">★ </span>':''}${e(t.title)}</div><div class="mb-task-meta">${e(taskLabel[t.category]||'Другое')} · ${t.task_date?ruDate(t.task_date):'Входящие'}${t.due_time?' · '+e(t.due_time):''}${t.repeat_rule&&t.repeat_rule!=='none'?' · ↻':''}${num(t.deferred_count)>0?` · Переносов: ${num(t.deferred_count)}`:''}</div>${t.notes?`<p class="mb-task-note">${e(t.notes)}</p>`:''}${t.reason&&!completed?`<span class="mb-reason">${e(reasonLabel[t.reason]||'Причина зафиксирована')}</span>`:''}</div><button class="mb-more" data-action="edit-task" data-id="${e(t.id)}" aria-label="Изменить задачу">···</button></div>${sub.length?`<div class="mb-subtasks">${sub.map(s=>`<button data-action="task-sub-toggle" data-id="${e(t.id)}" data-subid="${e(s.id)}" class="mb-subtask"><span class="mb-subcheck ${s.done?'done':''}">${s.done?'✓':''}</span>${e(s.title)}</button>`).join('')}</div>`:''}${!completed&&!muted?`<div class="mb-task-actions"><button class="mb-soft-btn" data-action="task-review" data-id="${e(t.id)}">Перенести / разобрать</button></div>`:''}</article>`}
function renderTasks(){const scope=state.taskScope||'today',list=scopedTasks(scope),all=state.data.tasks||[],done=all.filter(taskIsDone).length,pending=all.filter(t=>!taskIsDone(t)&&!['cancelled','skipped'].includes(t.status)).length;return `${pageHead('ПЛАН ВОСХОЖДЕНИЯ','Мои задачи','Записывай конкретные шаги, а не обещания. Если не сделал — выясни причину и измени следующий шаг.',`<button class="button" data-action="new-task">${icon('plus')} Задача</button>`)}<div class="mb-summary"><div><b>${pending}</b><span>В процессе</span></div><div><b>${done}</b><span>Завершено всего</span></div><div><b>${all.filter(t=>num(t.deferred_count)>0).length}</b><span>Были переносы</span></div></div><div class="mb-tabs" role="tablist" aria-label="Период задач">${[['today','Сегодня'],['week','Неделя'],['month','Месяц'],['inbox','Входящие'],['all','Все']].map(([id,label])=>`<button role="tab" aria-selected="${scope===id}" class="${scope===id?'selected':''}" data-action="task-scope" data-value="${id}">${label}</button>`).join('')}</div><section class="card mb-task-list"><div class="spread mb14"><h2>${({today:'План на сегодня',week:'Маршрут недели',month:'Задачи месяца',inbox:'Без даты',all:'Все задачи'})[scope]}</h2><span class="pill gray">${list.length}</span></div>${list.length?list.map(taskCard).join(''):'<div class="mb-empty"><span>✓</span><b>Пока пусто</b><p>Начни с одного конкретного действия, которое приблизит к цели.</p><button class="button secondary" data-action="new-task">Добавить задачу</button></div>'}</section><div class="mb-footnote">Незавершённые задачи прошлых дней видны в текущем периоде, чтобы не терять важное. Невыполненное — это информация, а не оценка тебя.</div>`}
function renderTodayLinks(){const todayLog=(state.data.daily_logs||[]).find(x=>x.log_date===today());const d=state.data.tasks.filter(x=>x.task_date===today());const done=d.filter(taskIsDone).length;return `<div class="mb-today-banner"><div><div class="eyebrow">ТВОЙ СЛЕДУЮЩИЙ ШАГ</div><strong>${d.length?`${done} из ${d.length} задач сегодня`:'Сегодня можно начать с одного шага'}</strong><p>${todayLog?.reflection_done?'Вечерний итог заполнен.':'Вечером зафиксируй, что получилось и что было трудно.'}</p></div><div class="mb-banner-actions"><button data-page="tasks" class="button secondary">Мои задачи</button><button data-page="reflection" class="button">${todayLog?.reflection_done?'Открыть итог':'Подвести итог'}</button></div></div>`}
function reflectionFromForm(data,old={},finished=false){const mode=String(data.reflection_mode||state.reflectionMode||'quick');const value=k=>String(data[k]??'').trim();const output={...old,log_date:data.log_date||today(),evening_energy:clamp(num(data.energy),1,10),evening_mood:clamp(num(data.mood),1,5),win_of_day:value('win_of_day'),blocked_why:value('blocked_why'),tomorrow_one:value('tomorrow_one'),thoughts:value('thoughts'),reflection_mode:mode,reflection_done:Boolean(finished),reflection_updated_at:new Date().toISOString()};
 // Don't erase full-review text when quick mode is saved.
 if(mode==='full'){Object.assign(output,{focus_score:clamp(num(data.focus_score),1,10),future_step:value('future_step'),avoidance:value('avoidance'),instead:value('instead'),today_learned:value('today_learned'),lesson_of_day:value('lesson_of_day')})}
 return output;}
function renderReflection(){const date=state.reflectionDate||today(),log=state.data.daily_logs.find(x=>x.log_date===date)||{},mode=state.reflectionMode||'quick';const reviewCount=state.data.daily_logs.filter(x=>x.reflection_done).length;const dates=lastDays(7);return `${pageHead('REFLECTION · ИТОГ ДНЯ','Вечерний дневник','Пять минут честности без самокритики. Запиши факты, наблюдения и один маленький шаг на завтра.')}<div class="mb-reflection-top"><div class="mb-night"><span>✦</span><div><b>Оглянись на сегодняшний путь</b><p>Даже трудный день можно использовать, чтобы лучше понять себя.</p></div></div><div class="mb-reflection-count">${reviewCount}<small>итогов сохранено</small></div></div><section class="card"><div class="spread mb14"><h2>${log.reflection_done?'Итог сохранён · можно дополнить':'Запись вечера'}</h2><span class="pill ${log.reflection_done?'':'gray'}">${log.reflection_done?'✓ Сохранено':'Черновик'}</span></div><div class="mb-tabs mb-mode-tabs">${[['quick','Быстрый · 2 мин'],['full','Полный · 5 мин']].map(([id,label])=>`<button class="${mode===id?'selected':''}" data-action="reflection-mode" data-value="${id}">${label}</button>`).join('')}</div><form data-form="reflection" data-autosave="encrypted" class="stack"><div class="form-grid">${field('log_date','Дата записи','date',date,`required max="${today()}"`)}${selectField('energy','Энергия сегодня',[...Array(10)].map((_,i)=>[i+1,`${i+1} / 10`]),String(log.evening_energy??(log.reflection_done?normalizedEnergy(log):6)))}${selectField('mood','Настроение',[['1','1 · Тяжело'],['2','2 · Ниже обычного'],['3','3 · Нейтрально'],['4','4 · Хорошо'],['5','5 · Отлично']],String(log.evening_mood??(log.reflection_done?log.mood:3)))}${mode==='full'?selectField('focus_score','Концентрация',[...Array(10)].map((_,i)=>[i+1,`${i+1} / 10`]),String(log.focus_score||6)):''}</div>${field('win_of_day','Моя маленькая или большая победа','textarea',log.win_of_day||'','placeholder="Что сегодня получилось?"')}${field('blocked_why','Что не получилось и почему?','textarea',log.blocked_why||'','placeholder="Факты без обвинения себя"')}${mode==='full'?`${field('future_step','Что я сделал ради будущего?','textarea',log.future_step||'','placeholder="Конкретное действие, а не намерение"')}${field('avoidance','Чего я избегал?','textarea',log.avoidance||'')}${field('instead','Что делал вместо важного?','textarea',log.instead||'')}${field('today_learned','Что узнал, чему научился?','textarea',log.today_learned||'')}${field('lesson_of_day','Главный вывод','textarea',log.lesson_of_day||'')}`:''}${field('thoughts','Мои мысли и идеи','textarea',log.thoughts||'','placeholder="Свободный дневник. Можно оставить пустым."')}${field('tomorrow_one','Одно улучшение завтра','textarea',log.tomorrow_one||'','placeholder="Реальный шаг на 5–15 минут"')}<div class="form-actions mb-save-actions"><span class="small muted" id="mb-autosave">Черновик сохраняется зашифрованно при вводе.</span><button type="submit" class="button">${icon('check')} Завершить обзор</button></div></form></section><section class="card mt20"><div class="card-header"><h2>Неделя: маленькие ежедневные шаги</h2><span class="pill gray">${dates.filter(d=>state.data.daily_logs.some(x=>x.log_date===d&&x.reflection_done)).length}/7 итогов</span></div><div class="mb-reflection-days">${dates.map(d=>{const log=state.data.daily_logs.find(x=>x.log_date===d),done=Boolean(log?.reflection_done);return `<button class="mb-day ${done?'done':''} ${date===d?'active':''}" data-action="reflection-date" data-value="${d}"><span>${new Intl.DateTimeFormat('ru-RU',{weekday:'short'}).format(new Date(d+'T12:00:00'))}</span><b>${d.slice(8)}</b><small>${done?'✓':'·'}</small></button>`}).join('')}</div><p class="small muted mt14">Пропуск — не провал. Можно вернуться к вчерашней записи, не прерывая собственный путь.</p></section>`}
function renderExperiments(){const list=[...(state.data.experiments||[])].sort((a,b)=>String(b.updated_at||b.created_at).localeCompare(String(a.updated_at||a.created_at)));const active=list.filter(x=>x.status==='testing'),concluded=list.filter(x=>['concluded','discarded'].includes(x.status));return `${pageHead('НЕИЗВЕСТНОСТЬ → ПРОВЕРКА','Лаборатория дохода','Тебе не нужно заранее знать идеальный бизнес. Каждую гипотезу можно превратить в маленькую проверку спроса.',`<button class="button" data-action="new-experiment">${icon('plus')} Новая проверка</button>`)}<div class="mb-summary"><div><b>${active.length}</b><span>В работе</span></div><div><b>${concluded.length}</b><span>Завершено</span></div><div><b>${list.reduce((s,x)=>s+num(x.payments),0)}</b><span>Оплат по проверкам</span></div></div><div class="card highlight mb14"><div class="eyebrow">ПРАВИЛО ФОКУСА</div><h2 class="mt8">Проверяй одну гипотезу за раз</h2><p class="small muted mt8">Новая идея — в «Банк идей». Активный эксперимент — здесь. Решение принимается по ответам и оплатам, а не по вдохновению.</p></div><div class="mb-experiment-list">${list.length?list.map(x=>`<article class="card mb-experiment"><div class="spread"><span class="pill ${x.status==='testing'?'':'gray'}">${e(({testing:'Проверяю',paused:'Пауза',concluded:'Завершено',discarded:'Остановлено'})[x.status]||'Новая')}</span><button class="button ghost small" data-action="edit-experiment" data-id="${e(x.id)}">Изменить</button></div><h2 class="mt14">${e(x.title)}</h2><p class="small muted mt8">${e(x.hypothesis)}</p><div class="mb-exp-stats"><span><b>${num(x.contacts)}</b> контактов</span><span><b>${num(x.replies)}</b> ответов</span><span><b>${num(x.payments)}</b> оплат</span><span><b>${money(x.earned_eur)}</b></span></div>${x.learnings?`<p class="mb-exp-note"><b>Вывод:</b> ${e(x.learnings)}</p>`:''}<div class="small muted mt14">Следующий шаг: ${e(x.next_step||x.test_action||'Ещё не записан')}</div>${x.deadline?`<div class="small muted mt8">Контрольная дата: ${ruDate(x.deadline)}</div>`:''}</article>`).join(''):'<section class="card mb-empty"><span>⛰</span><b>Первая проверка ещё впереди</b><p>Начни с идеи, которую реально проверить за семь дней, без больших вложений.</p><button class="button" data-action="new-experiment">Записать первую гипотезу</button></section>'}</div>`}
const SUMMIT_CATEGORIES=[['summit_home','Свой дом','Где и как я хочу жить?'],['summit_car','Машина мечты','Что я хочу себе позволить?'],['summit_finance','Финансовая свобода','Доход, капитал, резервы, отсутствие тяжёлых долгов'],['summit_health','Тело и устойчивость','Форма, спорт, энергия и спокойствие'],['summit_relationships','Семья и окружение','Отношения, друзья, общение'],['summit_experience','Стиль жизни','Путешествия, свобода, новые впечатления'],['summit_values','Кем я хочу стать?','Какие качества хочу развить?']];
function renderSummit(){const p=state.profile||{},debt=currentDebt();return `${pageHead('FROM ZERO TO SUMMIT','Моя вершина','Не статус ради статуса, а жизнь, которую ты действительно хочешь построить. Изменяй описание по мере того, как узнаёшь себя.')}<section class="mb-summit-hero"><div><div class="eyebrow">МАРШРУТ НАЧИНАЕТСЯ С РЕАЛЬНОСТИ</div><h2>От базового лагеря —<br>к своей высоте.</h2><p>Победа не измеряется количеством заполненных полей. Важны действия, устойчивость и настоящие изменения.</p></div></section><div class="grid cols2 mt20"><div class="card"><h2>Базовый лагерь</h2><div class="mb-summit-stat"><span>Старт</span><strong>${ruDate(p.started_at||today())}</strong></div><div class="mb-summit-stat"><span>Долг по записям</span><strong>${money(debt)}</strong></div><div class="mb-summit-stat"><span>Фокус сейчас</span><strong>${e(p.focus_title||'Найти работающий путь')}</strong></div><p class="small muted mt14">Непонятно, чем зарабатывать? Это отправная точка, а не приговор.</p></div><div class="card"><h2>Пять лагерей</h2>${[['Base Camp','Зафиксировать реальность'],['Camp I','Первые подтверждённые оплаты'],['Camp II','Регулярный доход и уменьшение долга'],['Camp III','Система, навыки и капитал'],['Summit','Свобода и желаемый образ жизни']].map(([a,b],i)=>`<div class="mb-camp"><span>${i===0?'●':'○'}</span><div><b>${a}</b><small>${b}</small></div></div>`).join('')}<p class="small muted mt14">Это карта этапов, не выдуманный процент до мечты.</p></div></div><section class="card mt20"><h2>Опиши свою вершину</h2><p class="small muted mt8">Твои ответы будут зашифрованы в локальном дневнике. Не нужно заполнять всё за один вечер.</p><form data-form="summit" class="stack mt20"><div class="grid cols2">${SUMMIT_CATEGORIES.map(([key,label,hint])=>field(key,label,'textarea',p[key]||'',`placeholder="${e(hint)}"`)).join('')}</div><button class="button" type="submit">Сохранить мою вершину ${icon('mountain')}</button></form></section>`}
function achievementItems(){const logs=(state.data.daily_logs||[]),refl=logs.filter(l=>l.reflection_done).sort((a,b)=>a.log_date.localeCompare(b.log_date)),completed=state.data.tasks.filter(taskIsDone),exps=state.data.experiments||[],english=sumOf(logs,'english_min'),learn=sumOf(logs,'learning_min'),sport=logs.filter(x=>num(x.exercise_min)>0).length,paid=exps.reduce((s,x)=>s+num(x.payments),0)+sumOf(logs,'sales_paid'),debt=currentDebt();let streak=0;for(let i=0;i<365;i++){const date=plusDays(today(),-i);if(i===0&&!refl.some(x=>x.log_date===date))continue;if(refl.some(x=>x.log_date===date))streak++;else break}return [
 ['base','Базовый лагерь','Ты начал личную экспедицию',Boolean(state.profile),'mountain'],['reflect1','Первое наблюдение','Первый завершённый вечерний обзор',refl.length>=1,'journal'],['reflect7','Семь отражений','7 завершённых вечерних итогов',refl.length>=7,'sun'],['streak7','Ритм восхождения','7 дней подряд с обзором',streak>=7,'calendar'],['steps10','Действие важнее планов','10 завершённых задач',completed.length>=10,'check'],['experiment','Первый эксперимент','Проверена хотя бы одна гипотеза',exps.some(x=>x.status==='concluded'),'compass'],['firstpay','Первая подтверждённая оплата','Есть записанная оплата по проверкам или продажам',paid>0,'wallet'],['english','Голос выше','10 часов английского',english>=600,'book'],['learn','Знания в действие','10 часов обучения',learn>=600,'book'],['sport','Сильное тело','10 дней с физической активностью',sport>=10,'heart'],['debt','Минус €500 долга','Остаток долга уменьшился минимум на €500',num(state.profile?.debt_baseline)-debt>=500&&num(state.profile?.debt_baseline)>0,'target']];}
function renderAchievements(){const list=achievementItems(),unlocked=list.filter(x=>x[3]).length;return `${pageHead('GARMIN ДЛЯ ЛИЧНОГО РОСТА','Достижения','Здесь награждаются реальные шаги: выдержка, возвращение к делу, завершение, обучение и первые деньги.')}<div class="mb-summary"><div><b>${unlocked}</b><span>Открыто</span></div><div><b>${list.length}</b><span>Всего достижений</span></div><div><b>${state.data.daily_logs.filter(x=>x.reflection_done).length}</b><span>Вечерних обзоров</span></div></div><section class="mb-badges">${list.map(x=>`<article class="mb-badge ${x[3]?'unlocked':'locked'}"><div class="mb-badge-icon">${icon(x[4])}</div><strong>${e(x[1])}</strong><p>${e(x[2])}</p><span>${x[3]?'✓ Достигнуто':'Ещё впереди'}</span></article>`).join('')}</section><div class="mb-footnote">Нет штрафов за пропуск. Награды не заменяют финансовые результаты и реальные изменения в жизни.</div>`}
function renderMountainWelcome(){const reflected=state.data.daily_logs.some(x=>x.log_date===today()&&x.reflection_done);return `<section class="mb-home-hero"><div class="mb-home-copy"><span>🏔 MONTBLANC · ЛИЧНАЯ ЭКСПЕДИЦИЯ</span><h2>Каждый шаг<br>имеет значение.</h2><p>Ты не обязан знать весь путь. Достаточно честно наблюдать, проверять идеи и двигаться дальше.</p><div class="mb-banner-actions"><button class="button" data-page="tasks">План дня ${icon('arrow')}</button><button class="button secondary" data-page="${reflected?'summit':'reflection'}">${reflected?'Моя вершина':'Итог дня'}</button></div></div></section>`}
function analyticsDates(period){if(period==='year')return [plusDays(today(),-364),today()];if(period==='month')return [plusDays(today(),-29),today()];return [plusDays(today(),-6),today()]}
function insightReport(period=state.analysisPeriod||'week'){const [start,end]=analyticsDates(period),logs=logBetween(start,end),tasks=state.data.tasks.filter(t=>(t.completed_at||t.task_date||'').slice(0,10)>=start&&(t.completed_at||t.task_date||'').slice(0,10)<=end),exps=(state.data.experiments||[]).filter(x=>(x.updated_at||x.started_at||'').slice(0,10)>=start),refl=logs.filter(x=>x.reflection_done),freq={};for(const t of tasks)if(t.reason){freq[t.reason]=(freq[t.reason]||0)+1}return {period,from:start,to:end,entries:logs.length,evening_reviews:refl.length,energy_avg:refl.some(l=>l.evening_energy!=null||l.energy!=null)?Math.round(avg(refl.filter(l=>l.evening_energy!=null||l.energy!=null).map(l=>l.evening_energy??normalizedEnergy(l)))*10)/10:null,mood_avg:refl.some(l=>l.evening_mood!=null||l.mood!=null)?Math.round(avg(refl.filter(l=>l.evening_mood!=null||l.mood!=null).map(l=>l.evening_mood??l.mood))*10)/10:null,focus_minutes:sumOf(logs,'focus_min'),english_minutes:sumOf(logs,'english_min'),learning_minutes:sumOf(logs,'learning_min'),sport_days:logs.filter(x=>num(x.exercise_min)>0).length,tasks:{in_scope:tasks.length,completed:tasks.filter(taskIsDone).length,deferred:tasks.filter(t=>num(t.deferred_count)>0).length,reasons:Object.entries(freq).map(([k,v])=>({reason:reasonLabel[k]||k,count:v}))},experiments:exps.map(x=>({title:x.title,status:x.status,contacts:x.contacts,replies:x.replies,payments:x.payments,earned_eur:x.earned_eur,lessons:x.learnings})),evening_notes:refl.map(l=>({date:l.log_date,win:l.win_of_day,barrier:l.blocked_why,what_avoided:l.avoidance,what_instead:l.instead,what_learned:l.today_learned,thoughts:l.thoughts,tomorrow:l.tomorrow_one})),sales:salesSummary(period==='week'?7:period==='month'?30:365),income_eur:state.data.finance_entries.filter(x=>x.kind==='income'&&x.entry_date>=start&&x.entry_date<=end).reduce((s,x)=>s+num(x.amount_eur),0),debt_current_eur:currentDebt()}}
function insightText(){const p=state.analysisPeriod||'week';return `MONTBLANC — личная экспедиция. Проанализируй ${p==='week'?'неделю':p==='month'?'30 дней':'365 дней'} по фактам. Покажи 3 реальные сильные стороны, повторяющиеся паттерны поведения, причины откладывания только как гипотезы, 3 приоритета на следующую неделю и конкретные действия на 5–15 минут. Отдельно отмечай, где данных недостаточно, не ставь психологических диагнозов и не смешивай мотивацию с доходом. Сначала задай 1 важный уточняющий вопрос, только если это существенно меняет выводы.\n\nДАННЫЕ (проверь личные мысли перед отправкой):\n${JSON.stringify(insightReport(p),null,2)}`}
async function copyInsightReport(){const txt=insightText();try{await navigator.clipboard.writeText(txt);notify('Отчёт скопирован. Проверь текст перед отправкой в ChatGPT.')}catch{const el=document.createElement('textarea');el.value=txt;el.setAttribute('readonly','');el.style.cssText='position:fixed;left:0;top:0;opacity:0';document.body.append(el);el.focus();el.select();const ok=document.execCommand('copy');el.remove();if(ok)notify('Отчёт скопирован. Проверь текст перед отправкой.');else{downloadInsightReport();notify('Копирование недоступно — скачан TXT для отправки.')}}}
function downloadInsightReport(){const url=URL.createObjectURL(new Blob([insightText()],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`montblanc-analysis-${state.analysisPeriod||'week'}-${today()}.txt`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function renderInsights(){const period=state.analysisPeriod||'week',x=insightReport(period);return `<section class="card mt20"><div class="spread"><div><div class="eyebrow">PATTERNS · ЧЕСТНЫЕ ДАННЫЕ</div><h2 class="mt8">Личное зеркало поведения</h2></div><span class="pill gray">${x.evening_reviews} вечерних итогов</span></div><div class="mb-tabs mt14">${[['week','7 дней'],['month','30 дней'],['year','365 дней']].map(([id,label])=>`<button class="${period===id?'selected':''}" data-action="analysis-period" data-value="${id}">${label}</button>`).join('')}</div><div class="mb-summary"><div><b>${x.tasks.completed}/${x.tasks.in_scope}</b><span>Задач закрыто</span></div><div><b>${x.energy_avg===null?'—':x.energy_avg}</b><span>Энергия (самооценка)</span></div><div><b>${x.experiments.length}</b><span>Проверок</span></div></div>${x.tasks.reasons.length?`<div class="mb-reasons"><h3>Причины трудностей</h3>${x.tasks.reasons.map(r=>`<div class="spread"><span>${e(r.reason)}</span><b>${r.count}</b></div>`).join('')}</div>`:'<p class="small muted mt14">Причины переносов появятся, когда ты начнёшь их отмечать.</p>'}<div class="mb-banner-actions mt20"><button class="button" data-action="copy-analysis">${icon('spark')} Для ChatGPT</button><button class="button secondary" data-action="download-analysis">${icon('download')} Скачать отчёт</button></div><p class="small muted mt14">В выгрузку входят личные заметки. Перед отправкой ИИ прочти отчёт и удали то, чем не хочешь делиться. Без твоего действия данные никуда не отправляются.</p></section>`}
async function scheduleNextRepeat(t){if(!t.repeat_rule||t.repeat_rule==='none'||!t.task_date)return;let date=t.task_date;for(let i=0;i<500;i++){date=t.repeat_rule==='monthly'?addMonths(date,1):plusDays(date,t.repeat_rule==='weekly'?7:1);if(date>today())break}if(date<=today())return;const series=t.series_id||t.id;if(state.data.tasks.some(x=>(x.series_id||x.id)===series&&x.task_date===date))return;await saveRecord('tasks',{title:t.title,notes:t.notes||'',task_date:date,category:t.category,is_main:t.is_main,priority:t.priority||'normal',repeat_rule:t.repeat_rule,series_id:series,subtasks:(t.subtasks||[]).map(s=>({id:uid(),title:s.title,done:false})),completed:false,status:'planned'})}
// Autosave plaintext only in memory; finalized/draft values are always encrypted when persisted.
let reflectionWriteTimeout=0;
document.addEventListener('input',event=>{const f=event.target.closest('form[data-form="reflection"]');if(!f||!state.local||!localCryptoKey)return;state.reflectionDraftTouched=true;clearTimeout(reflectionWriteTimeout);const indicator=document.getElementById('mb-autosave');if(indicator)indicator.textContent='Сохранение черновика…';reflectionWriteTimeout=setTimeout(async()=>{try{if(!f.isConnected)return;const data=formValues(f),day=String(data.log_date||today());if(day>today())return;const old=state.data.daily_logs.find(x=>x.log_date===day)||{};const row=reflectionFromForm(data,old,Boolean(old.reflection_done));await saveRecord('daily_logs',row);state.reflectionDraftTouched=false;const ind=document.getElementById('mb-autosave');if(ind)ind.textContent='Черновик зашифрован и сохранён на iPhone.'}catch(e){const ind=document.getElementById('mb-autosave');if(ind)ind.textContent='Не удалось сохранить. Нажми «Завершить обзор».'}},1100)});


function captureDraftOnRender(){if(!state.reflectionDraftTouched||!state.local||state.mode!=='app'||!localCryptoKey)return;const form=document.querySelector('form[data-form="reflection"]');if(!form||!form.isConnected)return;const data=formValues(form),day=data.log_date;if(!day||day>today())return;const existing=state.data.daily_logs.find(x=>x.log_date===day);const row=reflectionFromForm(data,existing||{},Boolean(existing?.reflection_done));if(existing)Object.assign(existing,row);else{row.id=uid();row.created_at=new Date().toISOString();state.data.daily_logs.push(row)}state.reflectionDraftTouched=false;void persistLocal().catch(error=>displayError(error))}
function renderPage(){switch(state.page){case 'dashboard':return renderDashboard();case 'tasks':return renderTasks();case 'reflection':return renderReflection();case 'experiments':return renderExperiments();case 'summit':return renderSummit();case 'achievements':return renderAchievements();case 'today':return renderToday();case 'goals':return renderGoals();case 'finance':return renderFinance();case 'sales':return renderSales();case 'habits':return renderHabits();case 'learning':return renderLearning();case 'english':return renderEnglish();case 'monthly':return renderMonthly();case 'ideas':return renderIdeas();case 'journal':return renderJournal();case 'review':return renderReview();case 'settings':return renderSettings();default:return renderDashboard()}}
function renderModal(m){let title='',body='',type=m.type;const g=state.data.goals.find(x=>x.id===m.id)||{},t=state.data.tasks.find(x=>x.id===m.id)||{},idea=state.data.ideas.find(x=>x.id===m.id)||{},journal=state.data.journal_entries.find(x=>x.id===m.id)||{};if(type==='goal'){title=m.id?'Изменить цель':'Новая цель';body=`<form data-form="goal" class="stack"><input name="id" type="hidden" value="${e(g.id||'')}">${field('title','Что конкретно хочешь получить?','text',g.title||'','required maxlength="160"')}${selectField('category','Сфера',[['finance','Доход'],['health','Тело'],['growth','Развитие'],['family','Семья'],['focus','Концентрация'],['travel','Путешествия'],['capital','Капитал'],['other','Другое']],g.category||'finance')}${selectField('horizon','Горизонт',[['90','90 дней'],['year','12 месяцев'],['long','Долгосрочно']],g.horizon||'90')}${selectField('metric_key','Обновление значения',[['','Вручную'],['daily_learning','Автоматически · учёба по дневным записям'],['weekly_english','Автоматически · английский за 7 дней'],['reserve_rate','Автоматически · доля перевода в резерв, %'],['monthly_income','Автоматически · доход за месяц'],['weekly_sport','Автоматически · тренировки за 7 дней'],['daily_english','Автоматически · английский за день с записью (среднее)'],['english_skill','По проверкам · средний уровень 4 навыков (A1=1, A2=2, B1=3)'],['weekly_family','Автоматически · время с семьёй за 7 дней'],['daily_social','Автоматически · соцсети (среднее за записанные дни)']],g.metric_key||'')}<div class="form-grid">${field('start_value','Начальная точка','number',g.start_value??0,'required step="any"')}${field('current_value','Текущее значение','number',g.current_value??0,'required step="any"')}${field('target_value','Цель (число)','number',g.target_value??1,'required step="any"')}${field('unit','Единица измерения','text',g.unit||'€','required')}${field('deadline','Срок','date',g.deadline||plusDays(today(),90))}${selectField('direction','Направление',[['up','Больше — лучше'],['down','Меньше — лучше']],g.direction||'up')}</div>${field('description','Зачем эта цель?','textarea',g.description||'')}${field('next_action','Следующее реальное действие','textarea',g.next_action||'')}<div class="form-actions">${g.id?`<button type="button" class="button dangerbtn" data-action="delete" data-table="goals" data-id="${e(g.id)}">Удалить</button>`:''}<button class="button" type="submit">Сохранить цель</button></div></form>`}
else if(type==='task'){title=m.id?'Изменить задачу':'Новая задача';const taskNotes=t.notes||'';body=`<form data-form="task" class="stack"><input name="id" type="hidden" value="${e(t.id||'')}">${field('title','Название задачи','text',t.title||'','required maxlength="240"')}${field('notes','Заметки, контекст, следующий шаг','textarea',taskNotes,'placeholder="Чтобы начать, мне нужно..."')}<div class="form-grid">${field('task_date','Дата · оставь пустым для Inbox','date',t.task_date===undefined?today():t.task_date)}${field('due_time','Время (необязательно)','time',t.due_time||'')}${selectField('priority','Приоритет',[['normal','Обычная'],['high','Высокая'],['low','Низкая']],t.priority||'normal')}${selectField('category','Сфера',[['finance','Доход'],['health','Тело'],['growth','Английский / развитие'],['family','Семья'],['focus','Концентрация'],['other','Другое']],t.category||'finance')}${selectField('repeat_rule','Повторение',[['none','Не повторять'],['daily','Каждый день'],['weekly','Каждую неделю'],['monthly','Каждый месяц']],t.repeat_rule||'none')}</div>${selectField('is_main','Роль',[['false','Обычная задача'],['true','Главный шаг дня']],String(Boolean(t.is_main)))}${field('subtask_text','Подзадачи · одна на строку','textarea',(t.subtasks||[]).map(x=>x.title).join('\n'),'placeholder="Первый небольшой шаг\nСледующий шаг"')}<div class="form-actions">${t.id?`<button type="button" class="button dangerbtn" data-action="delete" data-table="tasks" data-id="${e(t.id)}">Удалить</button>`:''}<button class="button" type="submit">Сохранить задачу</button></div></form>`}
else if(type==='idea'){title=m.id?'Изменить идею':'Новая идея';body=`<form data-form="idea" class="stack"><input name="id" type="hidden" value="${e(idea.id||'')}">${field('title','Название','text',idea.title||'','required maxlength="160"')}${field('description','В чём суть, кому полезно, как заработать?','textarea',idea.description||'','required')}${selectField('status','Статус',[['inbox','Новая'],['testing','Проверяю'],['parked','В запасе'],['discarded','Архив']],idea.status||'inbox')}${field('test_action','Как проверить спрос за 7 дней?','textarea',idea.test_action||'')}<div class="form-actions"><button class="button" type="submit">Сохранить идею</button></div></form>`}
else if(type==='idea-detail'){const comments=state.data.idea_comments.filter(x=>x.idea_id===idea.id).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));title=idea.title||'Идея';body=`<div class="spread"><span class="pill gray">${e(idea.status||'inbox')}</span><button class="button small secondary" data-action="edit-idea" data-id="${e(idea.id)}">Изменить</button></div><h3 class="mt20">Описание</h3><p class="small muted note-text mt8">${e(idea.description||'—')}</p><h3 class="mt20">Первая проверка</h3><p class="small muted note-text mt8">${e(idea.test_action||'Не задана')}</p><hr class="divider"/><h3>Мои комментарии (${comments.length})</h3>${comments.length?comments.map(c=>`<div class="comment"><div class="small muted">${ruDate((c.created_at||'').slice(0,10))}</div><p>${e(c.content)}</p></div>`).join(''):'<p class="small muted mt14">Комментариев пока нет.</p>'}<form data-form="comment" class="stack mt20"><input name="idea_id" type="hidden" value="${e(idea.id)}">${field('content','Новый комментарий','textarea','','required placeholder="Дополнительные мысли, результаты проверки, возражения"')}<div class="form-actions"><button class="button" type="submit">Добавить комментарий</button></div></form>`}
else if(type==='skill-check'){title='Контроль уровня английского';body=`<form data-form="skill-check" class="stack">${selectField('skill','Навык',[['speaking','Говорение'],['listening','Аудирование'],['reading','Чтение'],['writing','Письмо']],'speaking')}${selectField('level','Проверенный уровень',[['A1','A1'],['A2','A2'],['B1','B1']],'A1')}${field('evidence','На основании чего?','textarea','','placeholder="Пример: урок, запись речи, тест и результат. Самооценка ≠ сертификат"')}<div class="form-actions"><button type="submit" class="button">Сохранить результат</button></div></form>`}
else if(type==='journal'){title=m.id?'Изменить запись':'Новая запись';body=`<form data-form="journal" class="stack"><input name="id" type="hidden" value="${e(journal.id||'')}">${field('entry_date','Дата','date',journal.entry_date||today(),'required')}${field('title','Заголовок','text',journal.title||'','required maxlength="160"')}${field('content','Мысли и наблюдения','textarea',journal.content||'','required')}${selectField('tag','Тема',[['reflection','Рефлексия'],['win','Победа'],['challenge','Трудность'],['decision','Решение'],['family','Семья'],['other','Другое']],journal.tag||'reflection')}<div class="form-actions"><button class="button" type="submit">Сохранить запись</button></div></form>`}
else if(type==='finance'){title='Новая финансовая запись';body=`<form data-form="finance" class="stack">${field('entry_date','Дата','date',today(),'required')}${selectField('kind','Тип',[['income','Полученный доход'],['reserve','Перевод на резервный счёт'],['reserve_withdrawal','Снятие с резервного счёта'],['expense','Расход'],['debt_balance','Фактический остаток долга'],['debt_payment','Платёж по долгу']],'income')}${field('amount_eur','Сумма в евро','number','','required min="0" step="0.01"')}${field('description','Источник / пояснение','textarea','','placeholder="Например: платёж за консультацию, аренда квартиры..."')}<div class="form-actions"><button class="button" type="submit">Сохранить запись</button></div></form>`}
else if(type==='task-review'){title='Почему задача не выполнена?';body=`<form data-form="task-review" class="stack"><input type="hidden" name="id" value="${e(t.id||'')}"><div class="subtle-callout" style="padding:14px;border-radius:14px">${e(t.title||'')}</div>${selectField('task_status','Что произошло?',[['deferred','Перенести'],['skipped','Не сделано'],['cancelled','Отменить — неактуально']],m.status||'deferred')}${selectField('reason','Главная причина',[['time','Не хватило времени'],['energy','Мало энергии'],['distraction','Отвлечения / соцсети'],['uncertainty','Не знаю, с чего начать'],['overload','Задача слишком большая'],['fear','Страх отказа или ошибки'],['changed','Изменились обстоятельства'],['irrelevant','Потеряла актуальность'],['other','Другое']],t.reason||'time')}${field('reason_note','Что именно произошло?','textarea',t.reason_note||'','placeholder="Факт, который поможет понять повторяющийся паттерн"')}${field('new_date','Новая дата (для переноса)','date',plusDays(today(),1))}<button class="button" type="submit">Записать честно</button></form>`}
else if(type==='experiment'){const x=(state.data.experiments||[]).find(y=>y.id===m.id)||{};title=m.id?'Эксперимент: запись результатов':'Новый эксперимент';body=`<form data-form="experiment" class="stack"><input type="hidden" name="id" value="${e(x.id||'')}">${field('title','Название проверки','text',x.title||'','required maxlength="150"')}${field('hypothesis','Моя гипотеза · почему это может приносить деньги?','textarea',x.hypothesis||'','required')}${field('test_action','Что я реально проверю?','textarea',x.test_action||'','required')}${field('success_criteria','Как пойму, что проверка состоялась?','text',x.success_criteria||'','placeholder="Например: 10 контактов и ответы потенциальных клиентов"')}<div class="form-grid">${field('deadline','Контрольная дата','date',x.deadline||plusDays(today(),7))}${selectField('status','Статус',[['testing','Проверяю'],['paused','Пауза'],['concluded','Завершено'],['discarded','Остановил']],x.status||'testing')}</div><div class="form-grid">${field('contacts','Контакты','number',x.contacts??0,'min="0" step="1"')}${field('replies','Ответы','number',x.replies??0,'min="0" step="1"')}${field('payments','Оплаты','number',x.payments??0,'min="0" step="1"')}${field('earned_eur','Получено, €','number',x.earned_eur??0,'min="0" step="0.01"')}</div>${field('learnings','Что узнал и какие ошибки заметил?','textarea',x.learnings||'')}${field('next_step','Следующий разумный шаг','textarea',x.next_step||'')}<div class="form-actions">${x.id?`<button type="button" class="button dangerbtn" data-action="delete" data-table="experiments" data-id="${e(x.id)}">Удалить</button>`:''}<button class="button" type="submit">Сохранить эксперимент</button></div></form>`}
return `<div class="overlay" data-action="backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-header"><h2>${e(title)}</h2><button class="iconbtn" data-action="close" aria-label="Закрыть">×</button></div>${body}</div></div>`}
const makeGoal=(title,category,start,target,unit,horizon,deadline,description,next_action,direction='up')=>({title,category,start_value:num(start),current_value:num(start),target_value:num(target),unit,horizon,deadline,description,next_action,direction,status:'active'});
function seededGoals(profile){const in90=plusDays(today(),90),inYear=addMonths(today(),12);return [makeGoal('Доход €1 500 в месяц','finance',profile.income_baseline,profile.goal_90,'€','90',in90,'Один оффер, реальные контакты с клиентами и подтверждённые оплаты.','Выбрать узкую услугу и отправить первые 10 предложений.'),makeGoal('3 тренировки в неделю','health',profile.sport_baseline,3,'раз','90',in90,'Посильная регулярность вместо рывков.','Запланировать тренировку на 20–40 минут.'),makeGoal('Английский · 7 часов практики в неделю','growth',0,420,'мин','90',in90,'Путь A1 → B1 за 4 месяца, уровень проверяется контрольными заданиями.','Сегодня 60 минут английского, из них 15 минут говорить вслух.'),makeGoal('Учёба по 60 минут в день','growth',0,60,'мин/день','90',in90,'Книги / лекции + одно практическое применение.','Выбрать конкретную книгу или видео и выписать одно действие.'),makeGoal('150 минут с семьёй в неделю','family',0,150,'мин','90',in90,'Без экрана и без подсчёта любви в процентах.','Запланировать прогулку или совместное занятие.'),makeGoal('До 60 минут соцсетей в день','focus',profile.social_baseline,60,'мин/день','90',in90,'Сократить автоматическую прокрутку лент.','Первый рабочий блок — телефон вне комнаты.','down'),makeGoal('20% фактического дохода в резерв','capital',0,20,'%','90',in90,'Переводить деньги на отдельный счёт после каждого поступления.','Открыть отдельный резервный счёт и проверить бюджет семьи.'),makeGoal('Стабильный доход €2 500+','finance',profile.income_baseline,profile.goal_year,'€','year',inYear,'После проверки первой услуги систематизировать продажи.','Повторять то, что подтвердилось оплатами.'),makeGoal('B1 по английскому: подтверждение по 4 навыкам','growth',1,3,'уровень','year',addMonths(today(),4),'A1 сейчас. Уровень B1 — амбициозный ориентир, проверяем навыки по тестам и разговору.','Через 4 недели провести A1/A2 проверку по чтению, речи, письму и аудированию.'),makeGoal('Долгосрочный доход €20 000','capital',profile.income_baseline,20000,'€/мес','long',null,'Несколько источников, капитал, финансовая свобода.','В первую очередь создать один стабильный доход.'),makeGoal('Путешествия с семьёй','travel',0,1,'поездка','long',null,'Путешествия без долгового стресса.','После стабилизации бюджета запланировать поездку.'),makeGoal('Собственный дом','capital',0,1,'дом','long',null,'Жильё и чувство опоры для семьи.','Определить реалистичную финансовую модель после стабилизации.'),makeGoal('Инвестиционные квартиры','capital',0,2,'объекта','long',null,'Создание капитала на длинной дистанции.','Вернуться к расчётам после резерва и урегулирования долгов.')].map((g,i)=>({...g,metric_key:['monthly_income','weekly_sport','weekly_english','daily_learning','weekly_family','daily_social','reserve_rate','monthly_income','english_skill',null,null,null,null][i]}))}
async function saveProfile(profile){const row={...profile,user_id:sessionUser?.id||(state.local?'local':'demo')};if(state.demo||state.local){state.profile=row;if(state.local)await persistLocal();return row}const {data,error}=await client.from('profiles').upsert(row,{onConflict:'user_id'}).select().single();if(error)throw error;state.profile=data;return data}
async function saveRecord(table,record){if(!TABLES.includes(table))throw new Error('Недопустимая таблица');const row={...record,user_id:sessionUser?.id||(state.local?'local':'demo')};if(state.demo||state.local){let existing=-1;if(table==='daily_logs')existing=state.data[table].findIndex(x=>x.log_date===row.log_date);else if(table==='weekly_reviews')existing=state.data[table].findIndex(x=>x.week_end===row.week_end);else if(row.id)existing=state.data[table].findIndex(x=>x.id===row.id);if(existing>=0){row.id=state.data[table][existing].id;row.created_at=state.data[table][existing].created_at;state.data[table][existing]={...state.data[table][existing],...row}}else{row.id=uid();row.created_at=new Date().toISOString();state.data[table].push(row)}if(state.local)await persistLocal();return row}
  const {data,error}=await client.from(table).upsert(row,{onConflict:table==='daily_logs'?'user_id,log_date':table==='weekly_reviews'?'user_id,week_end':'id'}).select().single();if(error)throw error;const index=state.data[table].findIndex(x=>x.id===data.id);if(index<0)state.data[table].push(data);else state.data[table][index]=data;return data}
async function deleteRecord(table,id){if(!TABLES.includes(table))throw new Error('Недопустимая таблица');if(!state.demo&&!state.local){const {error}=await client.from(table).delete().eq('id',id);if(error)throw error}state.data[table]=state.data[table].filter(x=>x.id!==id);if(table==='ideas')state.data.idea_comments=state.data.idea_comments.filter(x=>x.idea_id!==id);if(state.local)await persistLocal()}
async function loadRemote(){state.mode='loading';render();const p=await client.from('profiles').select('*').eq('user_id',sessionUser.id).maybeSingle();if(p.error)throw p.error;state.profile=p.data;const all=await Promise.all(TABLES.map(async t=>{const r=await client.from(t).select('*').limit(5000);if(r.error)throw new Error(`${t}: ${r.error.message}`);return [t,r.data||[]]}));state.data=Object.fromEntries(all);state.mode=state.profile?'app':'setup';render()}
function demoData(){const d=Object.fromEntries(TABLES.map(k=>[k,[]]));const profile={user_id:'demo',income_baseline:350,debt_baseline:6500,goal_90:1500,goal_year:3000,social_baseline:150,sport_baseline:1,focus_title:'Проверить спрос на одну B2B-услугу и получить первый оплаченный тест',why_text:'Создать устойчивую жизнь и выбирать своё направление.',vision_text:'Больше энергии, время для семьи и регулярный доход.',started_at:plusDays(today(),-12)};const add=(table,row)=>{d[table].push({id:uid(),created_at:new Date().toISOString(),user_id:'demo',...row})};seededGoals(profile).forEach(x=>add('goals',x));const progress=[420,80,50,45,18,120,75,130,15,95,90,160,60,110];for(let i=0;i<14;i++){add('daily_logs',{log_date:plusDays(today(),i-13),sleep_hours:6.5+(i%4)*.2,energy:2+(i%4),mood:3,focus_min:progress[i],english_min:i%3===0?20:60,learning_min:i%4===0?25:60,learning_kind:i%2?'video':'book',learning_title:i%2?'Курс по цифровым продажам':'Книга о концентрации',learning_insight:'Одна идея для применения',social_min:Math.max(40,160-i*6),exercise_min:i%3===0?35:0,family_min:30,sales_contacts:2+i%7,sales_replies:i%3===0?1:0,sales_calls:i%4===0?1:0,sales_offers:i%5===0?1:0,sales_paid:i===11?1:0,one_action:'Демонстрационная запись',obstacle:''})}add('tasks',{title:'Составить одно конкретное предложение для клиентов',task_date:today(),category:'finance',is_main:true,completed:false});add('tasks',{title:'20 минут английского',task_date:today(),category:'growth',is_main:false,completed:false});add('tasks',{title:'Прогулка или тренировка 30 минут',task_date:today(),category:'health',is_main:false,completed:false});add('finance_entries',{entry_date:plusDays(today(),-10),kind:'income',amount_eur:350,description:'Демонстрационный доход'});add('finance_entries',{entry_date:plusDays(today(),-6),kind:'reserve',amount_eur:70,description:'Демонстрационное пополнение'});add('finance_entries',{entry_date:plusDays(today(),-3),kind:'debt_balance',amount_eur:6500,description:'Демонстрационный остаток'});add('skill_checks',{skill:'reading',level:'A1',assessed_on:plusDays(today(),-8),evidence:'Учебный пример'});add('skill_checks',{skill:'speaking',level:'A1',assessed_on:plusDays(today(),-8),evidence:'Учебный пример'});add('ideas',{title:'Небольшой B2B-сервис',status:'inbox',description:'Пример идеи, которую можно проверить на 10 разговорах с клиентами.',test_action:'Получить 3 предметных ответа от потенциальных покупателей'});add('journal_entries',{entry_date:plusDays(today(),-1),title:'Пример записи',content:'Сегодня сделал первый маленький шаг. Завтра повторю, без попытки объять всё.',tag:'reflection'});return {profile,data:d}}
function displayError(error){const msg=String(error?.message||error||'Неизвестная ошибка');console.error('MONTBLANC:',error);notify(msg,true)}
async function run(fn){if(busy)return;busy=true;try{await fn()}catch(err){displayError(err)}finally{busy=false}}
function go(page){state.page=page;state.menu=false;state.modal=null;render();window.scrollTo({top:0,behavior:'instant'})}
async function handleAction(btn,event){const action=btn.dataset.action,id=btn.dataset.id;switch(action){case 'demo':{const demo=demoData();state.profile=demo.profile;state.data=demo.data;state.demo=true;state.local=false;state.mode='app';go('dashboard');break}
case 'leave-demo':state.demo=false;state.mode=configReady?'auth':'landing';state.profile=null;state.data=Object.fromEntries(TABLES.map(k=>[k,[]]));render();break;
case 'local-open':state.mode='local-auth';render();break;
case 'back-landing':state.mode='landing';render();break;
case 'install-app':{const prompt=window.LIFEOS_INSTALL_PROMPT;if(prompt){await prompt.prompt();window.LIFEOS_INSTALL_PROMPT=null}else{notify('iPhone: Safari → Поделиться → На экран «Домой». Android: меню браузера → Установить приложение. Для установки нужен HTTPS-адрес.')}break}
case 'local-lock':lockLocal();break;
case 'encrypted-backup':await downloadEncrypted();notify('Зашифрованный архив скачан. Храни отдельно.');break;
case 'low-energy':state.lowEnergy=!state.lowEnergy;render();break;
case 'menu':state.menu=!state.menu;render();break;
case 'new-goal':state.modal={type:'goal'};render();break;
case 'edit-goal':state.modal={type:'goal',id};render();break;
case 'new-task':state.modal={type:'task'};render();break;
case 'edit-task':state.modal={type:'task',id};render();break;
case 'new-idea':state.modal={type:'idea'};render();break;
case 'edit-idea':state.modal={type:'idea',id};render();break;
case 'view-idea':state.modal={type:'idea-detail',id};render();break;
case 'new-journal':state.modal={type:'journal'};render();break;
case 'edit-journal':state.modal={type:'journal',id};render();break;
case 'new-finance':state.modal={type:'finance'};render();break;
case 'skill-check':state.modal={type:'skill-check'};render();break;
case 'copy-month':{const m=selectedMonth(),payload=JSON.stringify(monthlyPayload(m),null,2);const content='Проанализируй месячный прогресс MONTBLANC по фактам без догадок. Дай 3 сильные стороны, 3 отставания и конкретные действия на 7 дней. Данные без персональных дневников:\n'+payload;try{if(!navigator.clipboard?.writeText)throw Error('Clipboard API unavailable');await navigator.clipboard.writeText(content);notify('Месячные показатели скопированы. Вставь их в ChatGPT.')}catch{const ta=document.createElement('textarea');ta.value=content;ta.style.cssText='position:fixed;top:-999px';document.body.appendChild(ta);ta.select();const ok=document.execCommand('copy');ta.remove();notify(ok?'Месячные показатели скопированы':'Не удалось скопировать: скачай JSON в настройках',!ok)}break}
case 'month-prev':state.monthOffset=Math.max(-11,(state.monthOffset||0)-1);render();break;
case 'month-next':state.monthOffset=Math.min(0,(state.monthOffset||0)+1);render();break;
case 'generate-ai':await run(async()=>{if(state.demo||state.local){notify('Реальный AI-отчёт требует подключения облачного сервера. Используй «Скопировать показатели для ChatGPT».');return}const payload=monthlyPayload(selectedMonth());const {data,error}=await client.functions.invoke('monthly-coach',{body:{month:payload.month,stats:payload}});if(error)throw Error('Не удалось получить AI-отчёт. Проверь подключение Edge Function и API-ключ. '+(error.message||''));if(!data?.report||typeof data.report!=='string')throw Error('Ответ сервера не содержит отчёта');await saveRecord('ai_reports',{month_key:payload.month,report_text:data.report.slice(0,14000)});render();notify('Отчёт ChatGPT сохранён')});break;
case 'close':state.modal=null;render();break;
case 'backdrop':if(event.target===btn){state.modal=null;render()}break;
case 'filter-ideas':state.filter=btn.dataset.value;render();break;
case 'toggle-task':await run(async()=>{const t=state.data.tasks.find(x=>x.id===id);if(!t)return;const done=!taskIsDone(t);await saveRecord('tasks',{...t,completed:done,status:done?'done':'planned',completed_at:done?new Date().toISOString():null});if(done)await scheduleNextRepeat(t);render();if(done)notify('Шаг завершён. Отличная работа!')});break;
case 'task-review':state.modal={type:'task-review',id};render();break;
case 'task-scope':state.taskScope=btn.dataset.value||'today';render();break;
case 'task-sub-toggle':await run(async()=>{const t=state.data.tasks.find(x=>x.id===id),sub=t?.subtasks?.find(x=>x.id===btn.dataset.subid);if(!sub)return;await saveRecord('tasks',{...t,subtasks:t.subtasks.map(s=>s.id===sub.id?{...s,done:!s.done}:s)});render()});break;
case 'reflection-mode':captureDraftOnRender();state.reflectionMode=btn.dataset.value||'quick';render();break;
case 'reflection-date':state.reflectionDate=btn.dataset.value||today();render();break;
case 'new-experiment':state.modal={type:'experiment'};render();break;
case 'edit-experiment':state.modal={type:'experiment',id};render();break;
case 'analysis-period':state.analysisPeriod=btn.dataset.value||'week';render();break;
case 'copy-analysis':await copyInsightReport();break;
case 'download-analysis':downloadInsightReport();break;
case 'delete':if(!confirm('Удалить эту запись? Восстановить её через приложение не получится.'))return;await run(async()=>{await deleteRecord(btn.dataset.table,id);state.modal=null;render();notify('Запись удалена')});break;
case 'export':{if(state.local){await downloadEncrypted();notify('Зашифрованный архив скачан.');break}const backup={exported_at:new Date().toISOString(),version:1,profile:state.profile,data:state.data};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`life-os-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);notify('Файл создан. Храни его в защищённом месте.');break}
case 'logout':if(state.local){lockLocal();break}await run(async()=>{const {error}=await client.auth.signOut();if(error)throw error;sessionUser=null;state.profile=null;state.data=Object.fromEntries(TABLES.map(k=>[k,[]]));state.mode='auth';render()});break;
}}
async function submitForm(form){const data=formValues(form),kind=form.dataset.form;if(!kind)return;await run(async()=>{
if(kind==='login'){const {data:r,error}=await client.auth.signInWithPassword({email:String(data.email).trim(),password:data.password});if(error)throw error;sessionUser=r.user;await loadRemote();return}
if(kind==='local-auth'){const password=String(data.password||'');if(password.length<12)throw Error('Пароль должен содержать не менее 12 символов');if(!vaultStorage?.getItem(VAULT_KEY)&&password!==String(data.confirm_password||''))throw Error('Пароли не совпадают');try{await openLocal(password)}catch(err){throw Error('Не удалось открыть: неверный пароль или повреждённый архив.')}return}
if(kind==='sales'){const old=state.data.daily_logs.find(x=>x.log_date===today())||{};const keys=['sales_contacts','sales_replies','sales_calls','sales_offers','sales_paid'];const row={...old,log_date:today()};for(const key of keys){const v=Number(data[key]);if(!Number.isSafeInteger(v)||v<0||v>10000)throw Error('Введи целое неотрицательное число');row[key]=v}await saveRecord('daily_logs',row);render();notify('Продажи и контакты записаны');return}
if(kind==='setup'){const p={income_baseline:num(data.income_baseline),debt_baseline:num(data.debt_baseline),goal_90:num(data.goal_90),goal_year:num(data.goal_year),social_baseline:num(data.social_baseline),sport_baseline:num(data.sport_baseline),focus_title:String(data.focus_title).trim(),why_text:String(data.why_text||'').trim(),vision_text:String(data.vision_text||'').trim(),started_at:today()};await saveProfile(p);for(const g of seededGoals(p))await saveRecord('goals',g);await saveRecord('tasks',{title:'Выбрать одну B2B-услугу для проверки спроса',category:'finance',task_date:today(),is_main:true,completed:false});state.mode='app';go('dashboard');notify('Базовый лагерь создан. Твой маршрут начинается сегодня.');return}
if(kind==='settings'){const old=state.profile||{};await saveProfile({...old,income_baseline:num(data.income_baseline),debt_baseline:num(data.debt_baseline),goal_90:num(data.goal_90),goal_year:num(data.goal_year),social_baseline:num(data.social_baseline),sport_baseline:num(data.sport_baseline),focus_title:String(data.focus_title||'').trim(),why_text:String(data.why_text||'').trim(),vision_text:String(data.vision_text||'').trim()});render();notify('Настройки сохранены');return}
if(kind==='goal'){const old=state.data.goals.find(x=>x.id===data.id)||{};const goal={...old,title:String(data.title).trim(),category:data.category,horizon:data.horizon,start_value:num(data.start_value),current_value:num(data.current_value),target_value:num(data.target_value),unit:String(data.unit).trim(),deadline:data.deadline||null,direction:data.direction,metric_key:data.metric_key||null,description:String(data.description||'').trim(),next_action:String(data.next_action||'').trim(),status:old.status||'active'};await saveRecord('goals',goal);state.modal=null;render();notify('Цель сохранена');return}
if(kind==='task'){const old=state.data.tasks.find(x=>x.id===data.id)||{};const lines=String(data.subtask_text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,30);const oldSubs=old.subtasks||[];const subtasks=lines.map((name,i)=>{const oldMatch=oldSubs.find(x=>x.title===name)||oldSubs[i];return {id:oldMatch?.title===name?oldMatch.id:uid(),title:name,done:oldMatch?.title===name?Boolean(oldMatch.done):false}});await saveRecord('tasks',{...old,title:String(data.title).trim(),notes:String(data.notes||'').trim(),task_date:String(data.task_date||''),due_time:String(data.due_time||''),priority:data.priority||'normal',repeat_rule:data.repeat_rule||'none',subtasks,category:data.category,is_main:data.is_main==='true',completed:Boolean(old.completed),status:old.status||'planned'});state.modal=null;render();notify('Задача сохранена');return}
if(kind==='task-review'){const old=state.data.tasks.find(x=>x.id===data.id);if(!old)throw Error('Задача не найдена');const status=String(data.task_status||'deferred');if(status==='deferred'&&!data.new_date)throw Error('Выбери новую дату');await saveRecord('tasks',{...old,task_date:status==='deferred'?data.new_date:old.task_date,status,completed:false,reason:data.reason,reason_note:String(data.reason_note||'').trim(),last_review_at:new Date().toISOString(),deferred_count:num(old.deferred_count)+(status==='deferred'?1:0)});state.modal=null;render();notify('Причина сохранена, это полезные данные');return}
if(kind==='experiment'){const old=(state.data.experiments||[]).find(x=>x.id===data.id)||{};const contacts=Math.max(0,Math.floor(num(data.contacts))),replies=Math.max(0,Math.floor(num(data.replies))),payments=Math.max(0,Math.floor(num(data.payments)));if(replies>contacts)throw Error('Ответов не может быть больше контактов');await saveRecord('experiments',{...old,title:String(data.title||'').trim(),hypothesis:String(data.hypothesis||'').trim(),test_action:String(data.test_action||'').trim(),success_criteria:String(data.success_criteria||'').trim(),deadline:data.deadline||null,status:data.status||'testing',contacts,replies,payments,earned_eur:Math.max(0,num(data.earned_eur)),learnings:String(data.learnings||'').trim(),next_step:String(data.next_step||'').trim(),started_at:old.started_at||today(),updated_at:new Date().toISOString()});state.modal=null;render();notify('Эксперимент сохранён');return}
if(kind==='reflection'){clearTimeout(reflectionWriteTimeout);state.reflectionDraftTouched=false;const date=String(data.log_date||today());if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today())throw Error('Выбери корректную дату не позже сегодня');const old=state.data.daily_logs.find(x=>x.log_date===date)||{};const obj=reflectionFromForm(data,old,true);await saveRecord('daily_logs',obj);state.reflectionDate=date;state.modal=null;render();notify('Вечерний итог сохранён. Ещё один шаг на маршруте.');return}
if(kind==='summit'){const old=state.profile||{};await saveProfile({...old,summit_home:String(data.summit_home||'').trim(),summit_car:String(data.summit_car||'').trim(),summit_finance:String(data.summit_finance||'').trim(),summit_health:String(data.summit_health||'').trim(),summit_relationships:String(data.summit_relationships||'').trim(),summit_experience:String(data.summit_experience||'').trim(),summit_values:String(data.summit_values||'').trim()});render();notify('Твоя вершина обновлена');return}
if(kind==='daily'){const old=state.data.daily_logs.find(x=>x.log_date===today())||{};const obj={...old,log_date:today(),sleep_hours:data.sleep_hours===''?null:num(data.sleep_hours),energy:num(data.energy),energy_scale:10,mood:num(data.mood),focus_min:num(data.focus_min),social_min:num(data.social_min),exercise_min:num(data.exercise_min),english_min:num(data.english_min),learning_min:num(data.learning_min),learning_kind:String(data.learning_kind||'video'),learning_title:String(data.learning_title||'').trim(),learning_insight:String(data.learning_insight||'').trim(),family_min:num(data.family_min),one_action:String(data.one_action||'').trim(),obstacle:String(data.obstacle||'').trim()};await saveRecord('daily_logs',obj);render();notify('Чек-ин сохранён');return}
if(kind==='idea'){const old=state.data.ideas.find(x=>x.id===data.id)||{};const created=await saveRecord('ideas',{...old,title:String(data.title).trim(),description:String(data.description).trim(),status:data.status||'inbox',test_action:String(data.test_action||'').trim()});state.modal=old.id?{type:'idea-detail',id:created.id}:null;render();notify('Идея сохранена');return}
if(kind==='comment'){const idea_id=String(data.idea_id),idea=state.data.ideas.find(x=>x.id===idea_id);if(!idea)throw Error('Идея не найдена');await saveRecord('idea_comments',{idea_id,content:String(data.content).trim()});state.modal={type:'idea-detail',id:idea_id};render();notify('Комментарий добавлен');return}
if(kind==='skill-check'){await saveRecord('skill_checks',{skill:String(data.skill),level:String(data.level),assessed_on:today(),evidence:String(data.evidence||'').trim()});state.modal=null;render();notify('Самопроверка уровня сохранена');return}
if(kind==='journal'){const old=state.data.journal_entries.find(x=>x.id===data.id)||{};await saveRecord('journal_entries',{...old,title:String(data.title).trim(),entry_date:data.entry_date,content:String(data.content).trim(),tag:data.tag});state.modal=null;render();notify('Запись сохранена');return}
if(kind==='finance'){await saveRecord('finance_entries',{entry_date:data.entry_date,kind:data.kind,amount_eur:num(data.amount_eur),description:String(data.description||'').trim()});state.modal=null;render();notify('Финансовая запись сохранена');return}
if(kind==='review'){const old=state.data.weekly_reviews.find(x=>x.week_end===today())||{};await saveRecord('weekly_reviews',{...old,week_end:today(),wins:String(data.wins||'').trim(),blockers:String(data.blockers||'').trim(),adjustment:String(data.adjustment||'').trim(),next_week_focus:String(data.next_week_focus||'').trim()});render();notify('Недельный обзор сохранён');return}
})}
document.addEventListener('click',async event=>{const page=event.target.closest('[data-page]');if(page){go(page.dataset.page);return}const btn=event.target.closest('[data-action]');if(btn)await handleAction(btn,event)});
